DROP TABLE [sys_menu]
GO
CREATE TABLE [sys_menu] (
[menu_id] bigint NOT NULL IDENTITY(2000,1) ,
[menu_name] nvarchar(50) NOT NULL ,
[parent_id] bigint NULL DEFAULT ((0)) ,
[order_num] int NULL DEFAULT ((0)) ,
[path] nvarchar(200) NULL DEFAULT '' ,
[component] nvarchar(255) NULL DEFAULT NULL ,
[is_frame] int NULL DEFAULT ((1)) ,
[is_cache] int NULL DEFAULT ((0)) ,
[menu_type] nchar(1) NULL DEFAULT '' ,
[visible] nchar(1) NULL DEFAULT ((0)) ,
[status] nchar(1) NULL DEFAULT ((0)) ,
[perms] nvarchar(100) NULL DEFAULT NULL ,
[icon] nvarchar(100) NULL DEFAULT ('#') ,
[create_by] nvarchar(64) NULL DEFAULT '' ,
[create_time] datetime2(7) NULL ,
[update_by] nvarchar(64) NULL DEFAULT '' ,
[update_time] datetime2(7) NULL ,
[remark] nvarchar(500) NULL DEFAULT NULL 
)


GO
