-- ----------------------------
-- Procedure structure for sp_analyze_wcs_work_status
-- ----------------------------
DROP PROCEDURE [sp_analyze_wcs_work_status]
GO

CREATE PROCEDURE [sp_analyze_wcs_work_status]
    @begin_date DATETIME,
    @end_date DATETIME,
    @p_code INT OUTPUT,
    @p_msg NVARCHAR(MAX) OUTPUT
AS
BEGIN
    /* 关闭行数返回提示，提高性能 */
    SET NOCOUNT ON;

    BEGIN TRY
        /* 1. 声明用于统计的变量 */
        DECLARE @req_count INT = 0;
        DECLARE @sort_count INT = 0;
        DECLARE @conf_count INT = 0;

        DECLARE @req_no_conf INT = 0;
        DECLARE @req_no_sort INT = 0;
        DECLARE @sort_no_conf INT = 0;

        DECLARE @missing_conf_barcodes NVARCHAR(MAX) = '';

        /* 2. 统计基础请求数量 (针对全表流水) */
        SELECT 
            @req_count = ISNULL(SUM(CASE WHEN work_name = 'sd_request' THEN 1 ELSE 0 END), 0),
            @sort_count = ISNULL(SUM(CASE WHEN work_name = 'sd_report_sort' THEN 1 ELSE 0 END), 0),
            @conf_count = ISNULL(SUM(CASE WHEN work_name = 'sd_report_confirm' THEN 1 ELSE 0 END), 0)
        FROM wcs_log
        WHERE create_date >= @begin_date AND create_date <= @end_date;

        /* 3. 创建临时表，按条码聚合各阶段的状态 (1表示有，0表示无) */
        /* 注意：这里假设您的表中包含 barcode 字段。如果条码存在其他字段中，请将 barcode 替换为实际列名 */
        IF OBJECT_ID('tempdb..#TempBarcodeStats') IS NOT NULL
            DROP TABLE #TempBarcodeStats;

        SELECT 
            barcode,
            MAX(CASE WHEN work_name = 'sd_request' THEN 1 ELSE 0 END) AS has_req,
            MAX(CASE WHEN work_name = 'sd_report_sort' THEN 1 ELSE 0 END) AS has_sort,
            MAX(CASE WHEN work_name = 'sd_report_confirm' THEN 1 ELSE 0 END) AS has_conf
        INTO #TempBarcodeStats
        FROM wcs_log
        WHERE create_date >= @begin_date AND create_date <= @end_date
          AND barcode IS NOT NULL AND barcode <> ''
        GROUP BY barcode;

        /* 4. 计算差异数量 */
        SELECT 
            @req_no_conf = ISNULL(SUM(CASE WHEN has_req = 1 AND has_conf = 0 THEN 1 ELSE 0 END), 0),
            @req_no_sort = ISNULL(SUM(CASE WHEN has_req = 1 AND has_sort = 0 THEN 1 ELSE 0 END), 0),
            @sort_no_conf = ISNULL(SUM(CASE WHEN has_sort = 1 AND has_conf = 0 THEN 1 ELSE 0 END), 0)
        FROM #TempBarcodeStats;

        /* 5. 提取【有请求但无确认】的条码明细 */
        /* 使用 FOR XML PATH 将多行条码拼接成一个长字符串 (兼容各版本 SQL Server) */
        SELECT @missing_conf_barcodes = STUFF(
            (
                SELECT ',' + barcode
                FROM #TempBarcodeStats
                WHERE has_req = 1 AND has_conf = 0
                FOR XML PATH('')
            ), 1, 1, ''
        );

        /* 6. 组装返回的文本信息到 p_msg */
        SET @p_msg = 
            '【WCS 业务状态分析报告】' + CHAR(13) + CHAR(10) +
            '统计时间: ' + CONVERT(VARCHAR(20), @begin_date, 120) + ' 至 ' + CONVERT(VARCHAR(20), @end_date, 120) + CHAR(13) + CHAR(10) +
            '----------------------------------------' + CHAR(13) + CHAR(10) +
            '[1] 基础日志数量统计:' + CHAR(13) + CHAR(10) +
            '    - sd_request (请求数): ' + CAST(@req_count AS VARCHAR) + CHAR(13) + CHAR(10) +
            '    - sd_report_sort (分拣数): ' + CAST(@sort_count AS VARCHAR) + CHAR(13) + CHAR(10) +
            '    - sd_report_confirm (确认数): ' + CAST(@conf_count AS VARCHAR) + CHAR(13) + CHAR(10) +
            '----------------------------------------' + CHAR(13) + CHAR(10) +
            '[2] 异常差异统计 (基于条码去重对比):' + CHAR(13) + CHAR(10) +
            '    - 有请求但无确认: ' + CAST(@req_no_conf AS VARCHAR) + CHAR(13) + CHAR(10) +
            '    - 有请求但无分拣: ' + CAST(@req_no_sort AS VARCHAR) + CHAR(13) + CHAR(10) +
            '    - 有分拣但无确认: ' + CAST(@sort_no_conf AS VARCHAR) + CHAR(13) + CHAR(10) +
            '----------------------------------------' + CHAR(13) + CHAR(10) +
            '[3] 【有请求但无确认】异常条码明细:' + CHAR(13) + CHAR(10) +
            ISNULL(@missing_conf_barcodes, '完美！该时间段内所有请求均已确认。');

        /* 设置成功状态码 */
        SET @p_code = 0; 

    END TRY
    BEGIN CATCH
        /* 异常捕获与抛出 */
        SET @p_code = -1;
        SET @p_msg = '执行过程发生错误: ' + ERROR_MESSAGE();
    END CATCH

    /* 清理临时表防止内存泄漏 */
    IF OBJECT_ID('tempdb..#TempBarcodeStats') IS NOT NULL
        DROP TABLE #TempBarcodeStats;
END


GO

-- ----------------------------
-- Procedure structure for sp_AnalyzeWCSLog
-- ----------------------------
DROP PROCEDURE [sp_AnalyzeWCSLog]
GO

CREATE PROCEDURE [sp_AnalyzeWCSLog]
  @begin_date DATETIME,
    @end_date DATETIME,
    @p_code INT OUTPUT,
    @p_msg NVARCHAR(MAX) OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET @p_code = 0; /* 默认执行成功状态 */
    
    /* 0. 初始化分析头部信息 */
    SET @p_msg = '【分析时间段】: ' + CONVERT(VARCHAR, @begin_date, 120) + ' 至 ' + CONVERT(VARCHAR, @end_date, 120) + CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10);

    /* 声明各个基础统计变量 */
    DECLARE @req_cnt INT = 0, @conf_cnt INT = 0, @req46_cnt INT = 0, @rep_cnt INT = 0;
    
    /* 用于计算“多出的重复次数” */
    DECLARE @req_dup_extra_cnt INT = 0, @conf_dup_extra_cnt INT = 0;

    /* ========================================== */
    /* 1. 基础数量统计 */
    /* ========================================== */
    SELECT 
        @req_cnt = SUM(CASE WHEN work_name = 'sd_request' THEN 1 ELSE 0 END),
        @conf_cnt = SUM(CASE WHEN work_name = 'sd_report_confirm' THEN 1 ELSE 0 END),
        @req46_cnt = SUM(CASE WHEN work_name = 'sd_request_46' THEN 1 ELSE 0 END),
        @rep_cnt = SUM(CASE WHEN work_name = 'sd_report' THEN 1 ELSE 0 END)
    FROM wcs_log WITH(NOLOCK)
    WHERE create_date BETWEEN @begin_date AND @end_date;

    SET @p_msg = @p_msg + '【基础数量统计】' + CHAR(13) + CHAR(10);
    SET @p_msg = @p_msg + ' 1. sd_request 数量: ' + ISNULL(CAST(@req_cnt AS VARCHAR), '0') + CHAR(13) + CHAR(10);
    SET @p_msg = @p_msg + ' 2. sd_report_confirm 数量: ' + ISNULL(CAST(@conf_cnt AS VARCHAR), '0') + CHAR(13) + CHAR(10);
    SET @p_msg = @p_msg + ' 3. sd_request_46 数量: ' + ISNULL(CAST(@req46_cnt AS VARCHAR), '0') + CHAR(13) + CHAR(10);
    SET @p_msg = @p_msg + ' 4. sd_report 数量: ' + ISNULL(CAST(@rep_cnt AS VARCHAR), '0') + CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10);

    /* ========================================== */
    /* 创建临时表：提取该时间段内两类核心数据，极大提升后续对比效率 */
    /* ========================================== */
    IF OBJECT_ID('tempdb..#TmpReq') IS NOT NULL DROP TABLE #TmpReq;
    IF OBJECT_ID('tempdb..#TmpConf') IS NOT NULL DROP TABLE #TmpConf;

    /* 🚨 核心修复：使用 REPLACE 将 CHAR(5) 替换为竖线 | ，防止 XML 序列化失败，并便于阅读 */
    SELECT REPLACE(barcode, CHAR(5), '|') as barcode, COUNT(1) as cnt 
    INTO #TmpReq 
    FROM wcs_log WITH(NOLOCK) 
    WHERE create_date BETWEEN @begin_date AND @end_date 
      AND work_name = 'sd_request' 
      AND barcode IS NOT NULL 
      AND barcode <> '' 
    GROUP BY REPLACE(barcode, CHAR(5), '|');
    
    SELECT REPLACE(barcode, CHAR(5), '|') as barcode, COUNT(1) as cnt 
    INTO #TmpConf 
    FROM wcs_log WITH(NOLOCK) 
    WHERE create_date BETWEEN @begin_date AND @end_date 
      AND work_name = 'sd_report_confirm' 
      AND barcode IS NOT NULL 
      AND barcode <> '' 
    GROUP BY REPLACE(barcode, CHAR(5), '|');

    /* ========================================== */
    /* 2. sd_report_confirm 重复分析 */
    /* ========================================== */
    DECLARE @dup_conf_total INT = 0;
    DECLARE @dup_conf_str NVARCHAR(MAX) = '';
    
    SELECT @dup_conf_total = COUNT(1), @conf_dup_extra_cnt = ISNULL(SUM(cnt - 1), 0) FROM #TmpConf WHERE cnt > 1;

    SET @p_msg = @p_msg + '【分析1：sd_report_confirm 重复情况】' + CHAR(13) + CHAR(10);
    SET @p_msg = @p_msg + '重复条码个数: ' + CAST(@dup_conf_total AS VARCHAR) + ' 个 (共多出 ' + CAST(@conf_dup_extra_cnt AS VARCHAR) +' 次确认)' + CHAR(13) + CHAR(10);
    IF @dup_conf_total > 0
    BEGIN
        SELECT @dup_conf_str = STUFF(
            (SELECT TOP 100 ', ' + barcode + '(重' + CAST(cnt AS VARCHAR) + '次)' 
             FROM #TmpConf WHERE cnt > 1 FOR XML PATH(''), TYPE).value('.', 'NVARCHAR(MAX)'), 1, 2, '')
        IF @dup_conf_total > 100 SET @dup_conf_str = @dup_conf_str + ' ...(仅显示前100个)';
        SET @p_msg = @p_msg + '明细: ' + @dup_conf_str + CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10);
    END
    ELSE SET @p_msg = @p_msg + '结论: 无重复条码。' + CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10);

    /* ========================================== */
    /* 3. sd_request 重复分析 */
    /* ========================================== */
    DECLARE @dup_req_total INT = 0;
    DECLARE @dup_req_str NVARCHAR(MAX) = '';
    
    SELECT @dup_req_total = COUNT(1), @req_dup_extra_cnt = ISNULL(SUM(cnt - 1), 0) FROM #TmpReq WHERE cnt > 1;

    SET @p_msg = @p_msg + '【分析2：sd_request 重复情况】' + CHAR(13) + CHAR(10);
    SET @p_msg = @p_msg + '重复条码个数: ' + CAST(@dup_req_total AS VARCHAR) + ' 个 (共多出 ' + CAST(@req_dup_extra_cnt AS VARCHAR) +' 次请求)' + CHAR(13) + CHAR(10);
    IF @dup_req_total > 0
    BEGIN
        SELECT @dup_req_str = STUFF(
            (SELECT TOP 100 ', ' + barcode + '(重' + CAST(cnt AS VARCHAR) + '次)' 
             FROM #TmpReq WHERE cnt > 1 FOR XML PATH(''), TYPE).value('.', 'NVARCHAR(MAX)'), 1, 2, '')
        IF @dup_req_total > 100 SET @dup_req_str = @dup_req_str + ' ...(仅显示前100个)';
        SET @p_msg = @p_msg + '明细: ' + @dup_req_str + CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10);
    END
    ELSE SET @p_msg = @p_msg + '结论: 无重复条码。' + CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10);

    /* ========================================== */
    /* 4. 有 sd_request 但无 sd_report_confirm */
    /* ========================================== */
    DECLARE @req_no_conf_total INT = 0;
    DECLARE @req_no_conf_str NVARCHAR(MAX) = '';
    
    SELECT @req_no_conf_total = ISNULL(SUM(cnt), 0) FROM #TmpReq r WHERE NOT EXISTS (SELECT 1 FROM #TmpConf c WHERE c.barcode = r.barcode);

    SET @p_msg = @p_msg + '【分析3：有 请求(request) 但无 确认(confirm) 的条码】' + CHAR(13) + CHAR(10);
    SET @p_msg = @p_msg + '丢失确认的总数量: ' + CAST(@req_no_conf_total AS VARCHAR) + ' 个' + CHAR(13) + CHAR(10);
    IF @req_no_conf_total > 0
    BEGIN
        SELECT @req_no_conf_str = STUFF(
            (SELECT TOP 100 ', ' + barcode 
             FROM #TmpReq r WHERE NOT EXISTS (SELECT 1 FROM #TmpConf c WHERE c.barcode = r.barcode) FOR XML PATH(''), TYPE).value('.', 'NVARCHAR(MAX)'), 1, 2, '')
        IF @req_no_conf_total > 100 SET @req_no_conf_str = @req_no_conf_str + ' ...(仅显示前100个)';
        SET @p_msg = @p_msg + '明细: ' + @req_no_conf_str + CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10);
    END
    ELSE SET @p_msg = @p_msg + '结论: 无此类异常。' + CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10);

    /* ========================================== */
    /* 5. 有 sd_report_confirm 但无 sd_request */
    /* ========================================== */
    DECLARE @conf_no_req_total INT = 0;
    DECLARE @conf_no_req_str NVARCHAR(MAX) = '';
    
    SELECT @conf_no_req_total = ISNULL(SUM(cnt), 0) FROM #TmpConf c WHERE NOT EXISTS (SELECT 1 FROM #TmpReq r WHERE r.barcode = c.barcode);

    SET @p_msg = @p_msg + '【分析4：有 确认(confirm) 但无 请求(request) 的条码(可能是盲投或手动补录)】' + CHAR(13) + CHAR(10);
    SET @p_msg = @p_msg + '凭空出现的总数量: ' + CAST(@conf_no_req_total AS VARCHAR) + ' 个' + CHAR(13) + CHAR(10);
    IF @conf_no_req_total > 0
    BEGIN
        SELECT @conf_no_req_str = STUFF(
            (SELECT TOP 100 ', ' + barcode 
             FROM #TmpConf c WHERE NOT EXISTS (SELECT 1 FROM #TmpReq r WHERE r.barcode = c.barcode) FOR XML PATH(''), TYPE).value('.', 'NVARCHAR(MAX)'), 1, 2, '')
        IF @conf_no_req_total > 100 SET @conf_no_req_str = @conf_no_req_str + ' ...(仅显示前100个)';
        SET @p_msg = @p_msg + '明细: ' + @conf_no_req_str + CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10);
    END
    ELSE SET @p_msg = @p_msg + '结论: 无此类异常。' + CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10);

    /* ========================================== */
    /* 6. 数学平衡推导（为什么数量不一致的核心解密） */
    /* ========================================== */
    DECLARE @diff INT = ABS(ISNULL(@req_cnt, 0) - ISNULL(@conf_cnt, 0));
    SET @p_msg = @p_msg + '【★ 最终平衡推导结论 ★】' + CHAR(13) + CHAR(10);
    
    IF @diff = 0
    BEGIN
        SET @p_msg = @p_msg + '太棒了！本时间段内 sd_request ('+CAST(@req_cnt AS VARCHAR)+') 与 sd_report_confirm ('+CAST(@conf_cnt AS VARCHAR)+') 数量完全相等！';
    END
    ELSE
    BEGIN
        DECLARE @calc_diff INT = (@req_no_conf_total - @conf_no_req_total) + (@req_dup_extra_cnt - @conf_dup_extra_cnt);
        
        SET @p_msg = @p_msg + '>> 发现两者总数量相差: ' + CAST(@diff AS VARCHAR) + ' 条！' + CHAR(13) + CHAR(10);
        SET @p_msg = @p_msg + '>> 差异产生的原因及等式如下：' + CHAR(13) + CHAR(10);
        SET @p_msg = @p_msg + '【Request总数】 - 【Confirm总数】 = (有求无应) - (有应无求) + (重复请求多余数) - (重复确认多余数)' + CHAR(13) + CHAR(10);
        
        SET @p_msg = @p_msg + CAST(@req_cnt AS VARCHAR) + ' - ' + CAST(@conf_cnt AS VARCHAR) + ' = ' +
                              CAST(@req_no_conf_total AS VARCHAR) + ' - ' + CAST(@conf_no_req_total AS VARCHAR) + ' + ' +
                              CAST(@req_dup_extra_cnt AS VARCHAR) + ' - ' + CAST(@conf_dup_extra_cnt AS VARCHAR) + CHAR(13) + CHAR(10);
                              
        SET @p_msg = @p_msg + '等式核对结果相差: ' + CAST(@calc_diff AS VARCHAR) + '。详情条码请参照上方的明细进行排查追溯。' + CHAR(13) + CHAR(10);
    END

    /* 清理临时表 */
    IF OBJECT_ID('tempdb..#TmpReq') IS NOT NULL DROP TABLE #TmpReq;
    IF OBJECT_ID('tempdb..#TmpConf') IS NOT NULL DROP TABLE #TmpConf;
    
    SET @p_code = 200; /* 执行成功标记 */

END


GO

-- ----------------------------
-- Procedure structure for sp_bcr_msg_send_cc1
-- ----------------------------
DROP PROCEDURE [sp_bcr_msg_send_cc1]
GO

CREATE PROCEDURE [sp_bcr_msg_send_cc1]   
  @P_dvc_no VARCHAR(20), @p_send VARCHAR(4000) OUT, 
   @P_CODE VARCHAR(100) OUT,
   @p_CMD_NAME VARCHAR(2000) out
AS
DECLARE @v_hand_cmd_id VARCHAR(100);
DECLARE @V_CMD_NAME VARCHAR(4000);
DECLARE @V_CMD VARCHAR(4000);
declare @V_LMSG_TIME VARCHAR(100);
DECLARE
  @V_heartbeat VARCHAR(4000),
  @v_DATE1     DATETIME = GETDATE(),
  @v_s         INT = 0,
  @NAME        VARCHAR(4000);

BEGIN
  SELECT   TOP 1
           @v_hand_cmd_id = a.ID, @V_CMD_NAME    = A.CMD_NAME, @V_CMD         = A.CMD
  FROM     wcs_tools_hand_cmd A
  WHERE    A.DVC_NO = @P_dvc_no
  ORDER BY a.ID

  IF @@ROWCOUNT = 1
    BEGIN
      SET @p_send     = @V_CMD
      SET @p_CMD_NAME = @V_CMD_NAME

      /*执行完了就删除*/
      DELETE FROM wcs_tools_hand_cmd
      WHERE       ID = @V_HAND_CMD_ID

      /*SET @p_send=dbo.VarCharToHex(@p_send); */

      SET @v_s        = DATEDIFF(ms, @V_DATE1, GETDATE()) / 100

      SET @NAME       = 'PLC' + @P_dvc_no + '手动命令'
      EXEC [dbo].[sp_create_wcs_log]
	  	@V_CMD_NAME,                   /*1、作业名称 */
	  	NULL,                           /*2、容器号 */
	  	null,                           /*3、应去口 */
	  	NULL,                           /*4、实际口 */
		  NULL,                           /*5、读码器 */
		  NULL,                           /*6、分拣状态 */
		  @P_CODE,                        /*7、执行代码 */
	  	@V_CMD,                         /*8、执行信息 */
		  'wcs_tools_hand_cmd',              /*9、执行过程 */
		  @v_s,                           /*10、执行时间 */
	  	@P_dvc_no,                      /*11、dvc编号 */  
	  	NULL,                           /*12、备用1 */
	  	NULL,                           /*13、备用2 */
	  	NULL,                           /*14、备用3 */
		  NULL,                           /*15、备用4 */  
		  NULL,		                        /*16、备用5 */
			null                            /*16、重量 */
    END
    
    /*向不同的plc发送，特殊情况用到
   if @P_dvc_no='plc1'
      set @p_send='plc2=333333'; */
      
   /*set @p_send='333333'; */
  /* set @p_CMD_NAME='test '+@p_send */
END




GO

