	  	NULL,                           /*4、实际口 */
		  NULL,                           /*5、读码器 */
		  NULL,                           /*6、分拣状态 */
		  @P_CODE,                        /*7、执行代码 */
	  	@V_CMD,                         /*8、执行信息 */
		  'wcs_tools_hand_cmd',              /*9、执行过程 */
		  @v_s,                           /*10、执行时间 */
	  	@P_dvc_no,                      /*11、dvc编号 */  
	  	NULL,                           /*12、备用1 */
	  	NULL,                           /*13、备用2 */
	  	NULL,                           /*14、备用3 */
		  NULL,                           /*15、备用4 */  
		  NULL,		                        /*16、备用5 */
			null                            /*16、重量 */
    END
    
    /*向不同的plc发送，特殊情况用到
   if @P_dvc_no='plc1'
      set @p_send='plc2=333333'; */
      
   /*set @p_send='333333'; */
