-- ----------------------------
-- Procedure structure for sp_hc42_wms_plc_rev
-- ----------------------------
DROP PROCEDURE [sp_hc42_wms_plc_rev]
GO

CREATE PROCEDURE [sp_hc42_wms_plc_rev]/*称重回传 */
  @p_uuid varchar(100), 
	@p_Send VARCHAR(4000),
  @p_Rev VARCHAR(4000),
  @P_CODE VARCHAR(4000) OUT,
  @P_MSG VARCHAR(4000) OUT
AS
	DECLARE @v_Msg VARCHAR(4000) = '';
	DECLARE @v_PACK VARCHAR(4000) = '';
	declare @LOG varchar(1000);
	DECLARE @v_BCR_Nr VARCHAR(50) = '';
	DECLARE @dvc_no VARCHAR(50) = '';
	DECLARE @bcrMap varchar(50)='';
	DECLARE @v_DATE1 DATETIME = GETDATE();
	DECLARE @v_Destination01 VARCHAR(10),@barcode_len int;
	DECLARE @v_s INT = 0;
	DECLARE @v_NEW_REQ_NO INT;  /*应答报文中的顺序号*/
	declare @id bigint,@barcode varchar(200),@ParcelID varchar(20);
	declare @containerNo varchar(100),@planAddress varchar(1000),@taskSeq varchar(100),@status varchar(100),@errorMsg varchar(100),@taskNo varchar(100),
	@remark varchar(300),@planResultFlag varchar(100),@uniqueCode varchar(100),@temp1 varchar(100),@temp2 varchar(100),@temp3 varchar(100);
	declare @msg2 varchar(500),@sCode varchar(50)
	declare @pos varchar(50),@response varchar(100),@errorCode varchar(100),@v_NO_EXCEPTION_NO varchar(100),@tel_sn varchar(20)
	DECLARE @x   XML;
	BEGIN
	  BEGIN TRY
		  set	 @P_MSG = ''
			set	 @P_CODE = ''
			set @sCode='0'
      /*根据条码取出任务表的信息，组装目的地回复报文 */     
      SELECT @id=id,@barcode=barcode,@ParcelID=ParcelID,@v_BCR_Nr=bcr,@dvc_no=dvc_no,@tel_sn=temp1 FROM wcs_tools_parcel where msg=@p_send and type='cv' order by create_date asc
			delete from wcs_tools_parcel where id = @id 									 				         
     
		  BEGIN TRY
				 set @x=@p_Rev
				 SELECT  @response = v.value('(response)[1]','VARCHAR(100)'), 
                 @errorCode = v.value('(errorCode)[1]','VARCHAR(100)'),
                 @errorMsg = v.value('(errorMsg)[1]','VARCHAR(100)')
            FROM @x.nodes('/returnWeightInformationResponse') x(v)  
      END TRY
			BEGIN CATCH					
			END CATCH
		
			/*如果称重异常去异常口，其他根据任务分 */
			if ISNULL(@response,'') = '0' or isnull(@errorCode,'') <>''
			begin
				set @v_NO_EXCEPTION_NO=	dbo.f_tools_mem('bcr_no_0'+@v_BCR_Nr)	 		
				set @pos=	@v_NO_EXCEPTION_NO							
        /*set @msg2=',去异常,ToPos:'+ISNULL(@v_NO_EXCEPTION_NO,'')+',response:'+isnull(@response,'') */
				  /* +',errorCode:'+isnull(dbo.f_tools_mem('wms_error_code_'+@errorCode),'')+',ToPos:'	 */
			  set @msg2=',去异常,ToPos:'+ISNULL(@v_NO_EXCEPTION_NO,'')+',response:'+isnull(@response,'')
				  +',errorCode:'+isnull(@errorMsg,'')+',ToPos:'											 																																																	
		  end
			else
			begin
				SELECT top 1 @pos = TO_POS				
			  FROM wcs_task WHERE barcode=@barcode and task_type='cv'
				if @@rowcount=0
				begin
					SET @msg2    = ',无任务,ToPos:'	 	
					set	@pos = dbo.f_tools_mem('bcr_no_0'+@v_BCR_Nr)			 			
				end
				else
				begin	 						 			
		      SET @msg2    = ',ToPos:'	
				end			 							 														 			 	 		 															   
			end		
																		 
		 	set @v_Destination01=dbo.f_tools_WcsToPlc(@pos)													 																																																 																		 																																						 							 														 			 	 		 															  
									 
			SET @barcode_len=LEN(@barcode)				 			
			SET @v_Msg = 'FCFC0800'+@tel_sn+RIGHT(dbo.f_tools_inttohex(20+2+@barcode_len+8), 4)+ @ParcelID + '00000000'+RIGHT(dbo.f_tools_inttohex(@barcode_len), 4)
										  +DBO.f_tools_HEX(@Barcode)+'0001'+ RIGHT(dbo.f_tools_inttohex(@v_Destination01), 4)
											+'0000000000000000FDFD'																					 							 				 																			 	              
					
			EXEC sp_plc_pack_nr @v_NEW_REQ_NO OUT;
			SET @v_PACK  = 'FEFEFEFE' + RIGHT(dbo.f_tools_inttohex(@v_NEW_REQ_NO), 8) + RIGHT(dbo.f_tools_inttohex(LEN(@v_Msg) / 2 + 40), 4) +
												'0000' + '00000000' +  /*ACK确认数据包序号*/
																							RIGHT(dbo.f_tools_inttohex(99), 4) + RIGHT(dbo.f_tools_inttohex(1), 4) + RIGHT(dbo.f_tools_inttohex(4), 4)
												+ '000000000000' + dbo.f_plc_TimeStamp() + @v_Msg + 'FFFFFFFF';																																																 	 											 	 																									 																																																			 																																																																																																																																														 	 											 	 																									 					   
      SET @P_msg= @dvc_no+'&='+@v_PACK        			              
      
      SET @LOG = 
              '[cv_request_dest_1]' + ISNULL(@Barcode,'') + isnull(@msg2,'') +isnull(@v_Destination01,'')
							+ '('+isnull(@pos,'')+'),Bcr' +isnull(@v_BCR_Nr,'')+',id:' + CAST(dbo.f_tools_hextoint(@ParcelID) AS VARCHAR) 
    end try
    BEGIN CATCH
      SELECT @scode = ERROR_NUMBER(), @LOG  = ERROR_MESSAGE()
    END CATCH

    set @p_code=@LOG
    /*set @P_MSG='plc1&=363637' */
    SET @v_s    = DATEDIFF(ms, @V_DATE1, GETDATE()) / 100
    set @p_msg = isnull(@p_msg,'')    
    EXEC [dbo].[sp_create_wcs_log]
	  	'request_dest_1',            /*1、作业名称 */
	  	@barcode,                   /*2、容器号 */
	  	@v_Destination01,                   /*3、应去口 */
	  	null,                          /*4、实际口 */
		  @v_BCR_Nr,                           /*5、读码器 */
		  NULL,                           /*6、分拣状态 */
		  @sCODE,                        /*7、执行代码 */
	  	@LOG,                           /*8、执行信息 */
		  'sp_hc41_pdd_rev',       /*9、执行过程 */
		  @v_s,                           /*10、执行时间 */
	  	'hc41',                          /*11、dvc编号 */  
	  	@p_Rev,                      			/*12、备用1 */   
	  	@v_Msg,                           /*13、备用2 */
	  	@ParcelID,                         /*14、备用3 */
		  @p_send,                           /*15、备用4 */  
		  NULL,		                        /*16、备用5 */
			null                            /*16、重量 */                       
	END




GO

