	  /*set	 @p_Rev = '{"code":"0","message":"成功","data":{"resultCode":"1","content":{"orderNum":"7100155022","orderType":"OUT004","carrier":"20005","carrierType":"SF","shipTo":null,"soTo":null,"caseNum":"7100155022-000002","shipToDetail":null,"contact":null,"carrierText":"SF","shipType":"21","shipText":null,"matCode":null,"hdDefineStr4":"沈波//浙江/杭州市/萧山区/东流路701号","hdDefineStr5":"//11111112:/浙江/杭州市/滨江区/阡陌路556号2222","recipientprovname":null,"recipientcityname":null,"recipientareaname":null,"recipientaddress":null,"recipientname":null,"recipientmobile":null,"senderprovname":null,"sendercityname":null,"senderareaname":null,"senderaddress":null,"sendername":null,"sendermobile":null,"recptFlag":"","ebeln":null,"threeCode":"571","zzsub":"X","billNo":"848006419807","mbillNo":null,"bstkd":"","caseHd":null,"matText":null,"outOrderStr13":"2000176080/000020","outOrderStr14":"","outOrderStr17":"APO测试成品E81-DEV300中文","hdDefineStr15":"","stgLocCode":null,"matQty":null,"indSpeStkCode":"E","speStkNum":"2000176080/000020","batchNum":"","batchAttr20":null,"outOrderStr32":null,"matData":[{"outOrderStr13":"2000176080/000020","outOrderStr17":"APO测试成品E81-DEV300中文","batchNum":"","batchAttr20":null,"matQty":1.0,"matCode":"300200021"}],"caseStr1":null,"caseStr2":null,"caseStr3":null,"caseStr4":null,"caseStr5":null,"caseStr6":null}},"success":true,"type":null,"item":null,"status":null}' */
	  /*set @p_rev='{"code":"0","message":"成功","data":{"resultCode":"1","content":{"orderNum":"7100155049","orderType":"OUT004","carrier":"20001","carrierType":null,"shipTo":null,"soTo":null,"caseNum":"7100155049-000001","shipToDetail":null,"contact":null,"carrierText":"KD","shipType":"14","shipText":null,"matCode":null,"hdDefineStr4":"沈波//浙江/杭州市/萧山区/东流路701号","hdDefineStr5":"//11111112:/浙江/杭州市/滨江区/阡陌路556号2222","recipientprovname":null,"recipientcityname":null,"recipientareaname":null,"recipientaddress":null,"recipientname":null,"recipientmobile":null,"senderprovname":null,"sendercityname":null,"senderareaname":null,"senderaddress":null,"sendername":null,"sendermobile":null,"recptFlag":"","ebeln":null,"threeCode":"","zzsub":null,"billNo":"5889846525241","mbillNo":null,"bstkd":"","caseHd":{"orderType":null,"orderNum":"7100155049","caseNum":"7100155049000001","caseWei":null,"sapSyncFlag":0,"sendFlag":0,"usedFlag":0,"sendTime":null,"caseVol":null,"caseSealTime":null,"carrier":"20001","checkUser":null,"wbCode":"0050175BB0291753","whCode":"6001","dateCrt":null,"billNo":"5889846525241","zzsub":null,"boxCode":"7100155049000001","caseHdStr1":"202605091503668","caseHdStr2":"@800004382 3002000210000001","caseHdStr3":null,"caseHdStr4":null,"caseHdStr5":"0","caseHdStr6":"OUT004","printType":null,"customerType":"3","hdDefineStr6":null,"srcCarrier":null,"srcBillNo":null,"userMod":null,"dateMod":null,"userName":null,"reShip":null},"matText":null,"outOrderStr13":"2000176080/000020","outOrderStr14":"","outOrderStr17":"APO测试成品E81-DEV300中文","hdDefineStr15":"","stgLocCode":null,"matQty":null,"indSpeStkCode":"E","speStkNum":"2000176080/000020","batchNum":"","batchAttr20":null,"outOrderStr32":null,"matData":[{"outOrderStr13":"2000176080/000020","outOrderStr17":"APO测试成品E81-DEV300中文","batchNum":"","batchAttr20":null,"matQty":1.0,"matCode":"300200021"}],"caseStr1":null,"caseStr2":null,"caseStr3":null,"caseStr4":null,"caseStr5":null,"caseStr6":null}},"success":true,"type":null,"item":null,"status":null}' */
		set	 @P_CODE = ''
		set @p_msg=''
	  BEGIN TRY
		        /*根据条码取出任务表的信息，组装目的地回复报文 */     
      SELECT @id=id,@barcode=barcode,@ParcelID=ParcelID,@BCR_NO=bcr,@dvc_no=dvc_no,@tel_sn=tel_sn,
			   @wcsTaskNum_len=wcsTaskNum_len,@wcsTaskNum =wcsTaskNum
			  FROM wcs_tools_parcel where msg=@p_send and type='cv'
			/*delete from wcs_tools_parcel where id = @id 	 */
				
			/*解析贴标信息			 			 */
		  exec sp_hc44_analyzeLabelInfo	@wcsTaskNum,@p_rev,@to_pos out,@msg2 out	 
			
			/*向plc发送去向 	 */
			exec sp_plc_make_plc_msg	'08',@dvc_no,@wcsTaskNum,@wcsTaskNum,@to_pos,@to_pos,@ParcelID,
			  '','','',@P_msg out   			              
      
      SET @LOG = '[bcr_request_dest_44]'+ isnull(@msg2,'') +',to_pos:' +isnull(@Destination01,'')
				+ '('+isnull(@to_pos,'')+'),Bcr' +isnull(@BCR_NO,'')+',wcsTaskNum:'+isnull(@wcsTaskNum,'')
				+ +',taskType:ck,' +ISNULL(@Barcode,'')+ ',id:' + @ParcelID
    end try
    BEGIN CATCH
      SELECT @scode = ERROR_NUMBER(), @LOG  = ERROR_MESSAGE()
    END CATCH

    set @p_code=@LOG
    /*set @P_MSG='plc1&=363637' */
    SET @v_s    = DATEDIFF(ms, @V_DATE1, GETDATE()) / 100
    set @p_msg = isnull(@p_msg,'')    
    EXEC [dbo].[sp_create_wcs_log]
	  	'request_dest_44',            /*1、作业名称 */
	  	@barcode,                   /*2、容器号 */
	  	@Destination01,                   /*3、应去口 */
	  	null,                          /*4、实际口 */
		  @BCR_NO,                           /*5、读码器 */
		  NULL,                           /*6、分拣状态 */
		  @sCODE,                        /*7、执行代码 */
	  	@LOG,                           /*8、执行信息 */
		  'sp_hc44_wcsScanTaskReport_rev',       /*9、执行过程 */
		  @v_s,                           /*10、执行时间 */
	  	'hc44',                          /*11、dvc编号 */  
	  	@p_Rev,                      			/*12、备用1 */   
	  	@v_Msg,                           /*13、备用2 */
	  	@ParcelID,                         /*14、备用3 */
		  @p_send,                           /*15、备用4 */  
		  NULL,		                        /*16、备用5 */
			@wcsTaskNum                            /*16、重量 */                       
	END




