DROP PROCEDURE [sp_hc51_shopee_login_rev]
GO

CREATE PROCEDURE [sp_hc51_shopee_login_rev] /*多件格口释放接收 */
  @p_uuid varchar(100),  
	@p_Send VARCHAR(4000),
  @p_Rev VARCHAR(4000),
  @P_CODE VARCHAR(100) OUT,
  @P_MSG VARCHAR(4000) OUT
AS
  declare @taskNo varchar(400)='',@curAddress varchar(100)=''
	  ,@barcode varchar(4000),@wcsTaskNum varchar(50) 
		,@containerType varchar(40),@retcode varchar(200)='',@message varchar(1000)
		,@access_token varchar(400)								
		,@jsonSend varchar(4000),@containerCode varchar(200)
		,@pointCode	varchar(100)	
  DECLARE @v_DATE1 DATETIME = GETDATE(), @v_s INT = 0;
BEGIN
	BEGIN TRY		
		SELECT @retcode=retcode,@message=message FROM (SELECT a.parent_ID, a.NAME, a.StringValue
      FROM   f_tools_parseJSON(@p_Rev) a where isnull(a.name,'')in('message','retcode') )t1
        PIVOT (MAX(StringValue) FOR NAME IN(retcode,message)) AS t2		
	end try
	BEGIN CATCH
  END CATCH	
  
	if isnull(@retcode,'')='0'
	begin	
	  delete from wcs_tools_feedback where id=@p_uuid 	 
		  
	  SELECT @access_token=access_token FROM (SELECT a.parent_ID, a.NAME, a.StringValue
      FROM   f_tools_parseJSON(@p_Rev) a where isnull(a.name,'')in('access_token') )t1
        PIVOT (MAX(StringValue) FOR NAME IN(access_token)) AS t2	
    update wcs_mem_config set mem_item_oldvalue=mem_item_value,mem_item_value= isnull(@access_token,'')
      ,update_date= getdate()
      where mem_item_no='wms_access_token'
			
	  set @p_msg='[tws-login]login success,access_token:'+isnull(@access_token,'')		 				
	end
	else
	begin
	  update wcs_tools_feedback set flag='0' where id=@p_uuid 
		set @p_msg='[tws-login]login failed,message:'+isnull(@message,'')	
	end
	
	SET @v_s    = DATEDIFF(ms, @V_DATE1, GETDATE()) / 100
	EXEC [dbo].[sp_create_wcs_log]
	  	'tws_login',            /*1、作业名称 */
	  	null,                   /*2、容器号 */
	  	null,                   /*3、应去口 */
	  	null,                          /*4、实际口 */
		  NULL,                           /*5、读码器 */
		  NULL,                           /*6、分拣状态 */
		  @P_CODE,                        /*7、执行代码 */
	  	@p_msg,                           /*8、执行信息 */
		  'sp_hc51_shopee_login_rev',       /*9、执行过程 */
		  @v_s,                           /*10、执行时间 */
	  	'hc51',                          /*11、dvc编号 */  
	  	@p_Rev,                      			/*12、备用1 */   
	  	@p_Send,                           /*13、备用2 */
	  	null,                         /*14、备用3 */
		  null,                           /*15、任务状态 */  
		  NULL,		                        /*16、上车状态 */
			null                            /*16、任务号 */   
END


GO

