CREATE PROCEDURE [sp_hc54_shopee_sort_rev] /*多件格口释放接收 */
  @p_uuid varchar(100),  
	@p_Send VARCHAR(4000),
  @p_Rev VARCHAR(4000),
  @P_CODE VARCHAR(100) OUT,
  @P_MSG VARCHAR(4000) OUT
AS
  declare @taskNo varchar(400)='',@cur_pos varchar(100)=''
	  ,@barcode varchar(4000),@wcsTaskNum varchar(50) 
		,@containerType varchar(40),@code varchar(200)=''
		,@jsonSend varchar(4000),@containerCode varchar(200)
		,@pointCode	varchar(100),@shipment_id varchar(200)	
  DECLARE @v_DATE1 DATETIME = GETDATE(), @v_s INT = 0;
BEGIN
	BEGIN TRY		
		set @code = json_value(@p_Rev,'$.retcode')	  
		set @P_CODE ='0'
	end try
	BEGIN CATCH
  END CATCH	
	if isnull(@code,'')='0'
	begin		  		  	 
		select @barcode=barcode,@shipment_id=shipment_id,@cur_pos=curAddress from wcs_tools_feedback where id=@p_uuid 
			
		/*set @wcsTaskNum = json_value(@jsonSend,'$.data[0].wcsTaskNum')				 */
	  set @p_msg='[fms_sort]'+isnull(@barcode,'')+',shipment_id:'+isnull(@shipment_id,'')+',cur_pos:'+isnull(@cur_pos,'')+',Online sort upload successful'
		  
		delete from wcs_tools_feedback where id=@p_uuid 	 
		
		SET @v_s    = DATEDIFF(ms, @V_DATE1, GETDATE()) / 100
		EXEC [dbo].[sp_create_wcs_log]
	  	'fms_sort',            /*1、作业名称 */
	  	@barcode,                   /*2、容器号 */
	  	null,                   /*3、应去口 */
	  	@cur_pos,                          /*4、实际口 */
		  NULL,                           /*5、读码器 */
		  NULL,                           /*6、分拣状态 */
		  @P_CODE,                        /*7、执行代码 */
	  	@p_msg,                           /*8、执行信息 */
		  'sp_hc53_shopee_upload_image_rev',       /*9、执行过程 */
		  @v_s,                           /*10、执行时间 */
	  	'hc4',                          /*11、dvc编号 */  
	  	@p_Rev,                      			/*12、备用1 */   
	  	@p_Send,                           /*13、备用2 */
	  	null,                         /*14、备用3 */
		  null,                           /*15、任务状态 */  
		  NULL,		                        /*16、上车状态 */
			@shipment_id                           /*16、任务号*/   
	end
	else
	begin
	  update wcs_tools_feedback set flag='0' where id=@p_uuid 
	end
END

