CREATE PROCEDURE [sp_hc72_shopee_scan_send] /*多件集货完成 */
  @P_uuid VARCHAR(4000) OUT,
	@p_Send VARCHAR(4000) OUT,
  @P_CODE VARCHAR(100) OUT,
  @P_MSG VARCHAR(4000) OUT
AS
 /*向wms发送   设备状态回传接口*/
	DECLARE @header VARCHAR(4000) = '';/*设置的头*/
	DECLARE @body VARCHAR(4000) = '';/*发送的body*/
	DECLARE @body1 VARCHAR(4000) = '';/*发送的body*/
	DECLARE @id varchar(100)
/*	DECLARE @url VARCHAR(1000) = '/openapi/transport/asm_api/v1/single_receive'       */
  declare @uuid varchar(100),@barcode varchar(200)
  declare @timestamp varchar(100)

  DECLARE @v_DATE1 DATETIME = GETDATE(), @v_s INT = 0;
BEGIN 
  set @p_uuid=''
  set @p_send=''
  
  select top 1 @id=id,@barcode=barcode
	 from wcs_tools_feedback where type='scan_offline' and flag='0' order by create_date asc
  IF @@rowcount=1
  BEGIN 
    update wcs_tools_feedback set flag='1' where id=@id
    
    set @uuid = LOWER(REPLACE(CAST(NEWID() AS VARCHAR(36)), '-', ''))
    set @timestamp = DATEDIFF(SECOND, '1970-01-01 00:00:00', GETUTCDATE())
  
    set @header= 'Content-Type@@application/json'  
    set @body1= '{
      "data": {
      "access_token":"'+dbo.f_tools_mem('wms_access_token')+'",
      "scan_number_list": ["'+isnull(@barcode,'')+'"],
      "weight": 300,
      "machine_id": "'+dbo.f_tools_mem('wms_machine_id')+'",
      "whs_id": "'+dbo.f_tools_mem('wms_whs_id')+'",
      "request_id": "'+isnull(@uuid,'')+'",
      "lang": "ZH"
      },
      "timestamp": '+isnull(@timestamp,'')+'
      }'
    set @body = '{"jwt":"'+'{$SHOPEE2;HS256;'+dbo.f_tools_mem('wms_jwt_account')+';'+dbo.f_tools_mem('wms_jwt_secret')+';'+isnull(@body1,'')+'$}'+'"}'
	  		 		  
    set @p_send= isnull(@header,'')+'#####'+isnull(@body,'')
    
    set @P_uuid= @id
  
  end
END


