CREATE procedure [sp_label_heartbeat_msg] @p_dvc_no varchar(50),@p_send varchar(4000) out
as
declare @lastTime datetime,@dt2 datetime,@i1 int;
begin
  
  
  select @lastTime= case when dataLength(isnull(update_date,''))<8 then '1970-01-01 00:00:00'
    else update_date end
	from wcs_dvc where dvc_no=@p_dvc_no
	set @dt2= getdate()
	set @i1=datediff(ss,@lastTime,@dt2)
	if @i1 >10
	begin
	  set @p_send = '~HS' 
		update wcs_dvc set UPDATE_DATE=convert(varchar,GETDATE(),120) where dvc_no= @P_dvc_no  
	end
end

GO

-- ----------------------------
-- Procedure structure for sp_label_msg_rev
-- ----------------------------
DROP PROCEDURE [sp_label_msg_rev]
GO
CREATE PROCEDURE [sp_label_msg_rev]
  @P_dvc_no VARCHAR(20),  /*PLC的dvc_no*/
  @p_REV VARCHAR(4000),  /*接收到的报文*/
  @P_SEND VARCHAR(4000) OUT,  /*回复ACK和报文*/
  @p_Pack_Nr INT OUT,  /*上一次数据包序号*/
  @P_CODE VARCHAR(20) OUT,
  @P_MSG VARCHAR(4000) OUT  /*显示在mem的信息*/
AS
  declare @v_AlarmMsg varchar(100),@err varchar(50),@err_all varchar(200)
BEGIN
	update wcs_dvc set UPDATE_DATE=convert(varchar,GETDATE(),120) where dvc_no= @P_dvc_no  
  IF @p_REV in('register_online','register_offline')
    BEGIN
      SET @P_SEND = '';
      SET @P_MSG  = '';
      RETURN;
    END
    
  set @v_AlarmMsg= dbo.f_tools_Hex_To_Char(@p_rev)
  while charindex('1',@v_AlarmMsg) !=0
  begin
    declare @index1 int=charindex('1',@v_AlarmMsg)
    set @err = dbo.f_tools_mem('label_error_code_E'+cast(@index1 as varchar))    
    set @err_all = isnull(@err_all,'') +'&&'+ isnull(@err,'') 
    set @v_AlarmMsg= stuff(@v_AlarmMsg,@index1,1,'0')
  end

  SET @P_CODE      = '0'
  SET @P_SEND      = ''
  if isnull(@err_all,'')!='&&'
    SET @P_MSG       = '[label_rev]'+ @err_all

END

GO

-- ----------------------------
-- Procedure structure for sp_label_msg_send
-- ----------------------------
DROP PROCEDURE [sp_label_msg_send]
GO
CREATE PROCEDURE [sp_label_msg_send]
  @P_dvc_no VARCHAR(20), 
	@p_send VARCHAR(4000) OUT, 
   @P_CODE VARCHAR(100) OUT,
   @p_CMD_NAME VARCHAR(2000) out
AS
DECLARE @v_hand_cmd_id VARCHAR(100);
DECLARE @V_CMD_NAME VARCHAR(4000);
DECLARE @V_CMD VARCHAR(4000);
declare @V_LMSG_TIME VARCHAR(100);
DECLARE
  @V_heartbeat VARCHAR(4000),
  @v_DATE1     DATETIME = GETDATE(),
  @v_s         INT = 0,
  @NAME        VARCHAR(4000),
  @CMD_NAME        VARCHAR(4000) = '' ,
	@label_msg varchar(4000),@label_template_no varchar(100)='bb1';

BEGIN  
  SELECT   TOP 1
           @v_hand_cmd_id = a.id, @V_CMD_NAME    = A.CMD_NAME, @V_CMD         = A.CMD
  FROM     wcs_tools_hand_cmd A
  WHERE    A.DVC_NO = @P_dvc_no
  ORDER BY a.id

  IF @@ROWCOUNT = 1
    BEGIN
      /*执行完了就删除*/
      DELETE FROM wcs_tools_hand_cmd
      WHERE       id = @V_HAND_CMD_ID
      set @p_CMD_NAME=@V_CMD_NAME
			set @p_send = dbo.f_tools_HEX(@V_CMD)									      

      SET @v_s        = DATEDIFF(ms, @V_DATE1, GETDATE()) / 100

      SET @NAME       =  @P_dvc_no + '手动命令'
      
	      EXEC [dbo].[sp_create_wcs_log]
		  	'label_send',                   /*1、作业名称 */
		  	NULL,                           /*2、容器号 */
		  	null,                           /*3、应去口 */
		  	NULL,                           /*4、实际口 */
			  NULL,                           /*5、读码器 */
			  NULL,                           /*6、分拣状态 */
			  @P_CODE,                        /*7、执行代码 */
		  	@V_CMD_NAME,                         /*8、执行信息 */
			  'sp_label_msg_send',              /*9、执行过程 */
			  @v_s,                           /*10、执行时间 */
		  	@P_dvc_no,                      /*11、dvc编号 */  
		  	NULL,                           /*12、备用1 */
		  	NULL,                           /*13、备用2 */
		  	NULL,                           /*14、备用3 */
			  NULL,                           /*15、任务状态 */  
			  NULL,		                        /*16、上车状态 */
				null                            /*16、任务号 */
		  return																							 	 
    END
    else
    begin    
      exec dbo.sp_label_heartbeat_msg @p_dvc_no,@v_cmd output
      if isnull(@v_cmd,'')<>''
      begin
        set @p_send=dbo.f_tools_HEX(@v_cmd) 
        set @p_cmd_name='heartbeat'
      end
    end  
  
  
END

GO

-- ----------------------------
-- Procedure structure for sp_label_print
-- ----------------------------
DROP PROCEDURE [sp_label_print]
GO
CREATE PROCEDURE [sp_label_print] /*打印 */
  @itemId varchar(100), 
	@type varchar(100),  
  @P_CODE VARCHAR(100) OUT,
  @P_MSG VARCHAR(4000) OUT
AS
  DECLARE @v_DATE1 DATETIME = GETDATE(), @v_s INT = 0;
	declare @wms_to_pos varchar(20),@order_list_json VARCHAR(1000) = '',
	 @timestamp varchar(100),@machine_package_number varchar(200),
	 @body varchar(4000),@header VARCHAR(4000),@Send VARCHAR(4000),
	 @to varchar(50),@last_zpl varchar(max) 	 
BEGIN
  set @p_code='0'
	BEGIN TRY	
	  select @wms_to_pos=wms_to_pos,@to=last_to,@last_zpl=last_zpl from wcs_tools_label where id=@itemId  
	  if isnull(@type,'') ='1' 
		begin
	    update wcs_tools_label set isPrinted='1',parcel_num=0 where id=@itemId 						 												
																				 								 			 							 	 												
			 set @timestamp = DATEDIFF(SECOND, '1970-01-01 00:00:00', GETUTCDATE())	
			/* ============================================================================== */
        /* 2. 拼接 order_list 数组 (基于 wcs_tools_label_detail 组装) */
        /* ============================================================================== */
        SELECT @order_list_json = STUFF((
            SELECT ',{"scan_order_id":"' + ISNULL(barcode, '') + '"'
                 + ',"weight_flag":true,"weight":' + ISNULL(NULLIF(weight, ''), '0')
                 + ',"dimension_flag":true,"length":' + ISNULL(NULLIF(length, ''), '0')
                 + ',"width":' + ISNULL(NULLIF(width, ''), '0')
                 + ',"height":' + ISNULL(NULLIF(height, ''), '0') + '}'
            FROM wcs_tools_label_detail
            WHERE wms_to_pos = @wms_to_pos
              AND flag = '0' /* 0表示当前尚未完成集包/未打印的明细 */
            FOR XML PATH(''), TYPE).value('.', 'VARCHAR(MAX)'), 1, 1, '');
        
        update wcs_tools_label_detail set flag='1'
           WHERE wms_to_pos = @wms_to_pos AND flag = '0'

        /* 防止明细为空导致 JSON 语法错误 */
        IF @order_list_json IS NULL 
            SET @order_list_json = '';	
						
				set @header= 'Content-Type@@application/json;Authorization@@Bearer {$SHOPEE1;HS256;JWT;'+dbo.f_tools_mem('wms_jwt_account')+';'+dbo.f_tools_mem('wms_jwt_secret')+'$}'
				
				/* 生成分拣机分包编号 machine_package_number (文档建议格式包含豪秒级时间戳，这里以秒级代替演示) */
        SET @machine_package_number = 'mpn_' + dbo.f_tools_mem('wms_jwt_account') + '_'+ISNULL(@wms_to_pos, '') + '_' + @timestamp;
									 																											 
				/* 4. 拼接 Body JSON */
        /* 根据 3.4.3 接口文档，传入 print_type 为 zpl，并将明细数组嵌进去 */
        SET @body = '{
          "entrance_id" : "' + dbo.f_tools_mem('wms_machine_id') + '",
          "entrance_type" : 4,
          "operator" : "' + dbo.f_tools_mem('wms_account') + '",
          "scan_time" : ' + @timestamp + ',
          "machine_package_number" : "' + @machine_package_number + '",
          "print_type" : "zpl",
          "order_list" : [' + @order_list_json + ']
          }'		
        set @send= isnull(@header,'')+'#####'+isnull(@body,'')	
        
        INSERT INTO wcs_tools_feedback( type,flag,curAddress,msg) 
				  VALUES ('pack','0',@wms_to_pos,@send)						 								    			  
																													 			 								 								    
			set @p_msg='print success,id='+isnull(@itemId,'')
		end
		else
		begin
			INSERT INTO wcs_tools_hand_cmd( dvc_no,cmd_name,cmd) 
		    VALUES (dbo.f_tools_mem('print_chute_'+@wms_to_pos),'Reprint_'+@to,@last_zpl)
			set @p_msg='Reprint success,id='+isnull(@itemId,'')
		end	  	  		
	end try
	BEGIN CATCH
	  set @p_code='-1'
		set @p_msg='print error'+isnull(@type,'') +',id='+isnull(@itemId,'')
  END CATCH		
            
	  
END

GO

-- ----------------------------
-- Procedure structure for sp_plc_make_plc_msg
-- ----------------------------
DROP PROCEDURE [sp_plc_make_plc_msg]
GO

CREATE PROCEDURE [sp_plc_make_plc_msg] 
  @type varchar(10), @dvc_no VARCHAR(50), @barcode varchar(200),
  @to_pos varchar(500), /* 加长长度以容纳多个逗号分隔的格口 */
  @label varchar(20),@ParcelID varchar(20), @bcr_no varchar(50),
	@p_send VARCHAR(8000) OUT
AS
DECLARE @barcode_len int, @v_Msg VARCHAR(MAX) = '',
  @NEW_REQ_NO INT, @v_PACK VARCHAR(MAX) = '',
  @msg_len INT, @total_pack_len INT,
  
  /* 多格口解析专用变量 */
  @ChuteQty INT = 0,
  @Chutes_Hex VARCHAR(MAX) = '',
  @temp_to_pos VARCHAR(500) = @to_pos + ',', /* 尾部加逗号方便统一截取 */
  @comma_idx INT,
  @single_pos VARCHAR(20),
  @single_plc_pos VARCHAR(10)
        
BEGIN
  if @type in ('08') /* 目的地回复 */
  begin  
      SET @barcode_len = LEN(@barcode)
      
      /* --- 1. 解析多格口字符串 (兼容单格口) --- */
      WHILE CHARINDEX(',', @temp_to_pos) > 0
      BEGIN
          SET @comma_idx = CHARINDEX(',', @temp_to_pos)
          SET @single_pos = LTRIM(RTRIM(SUBSTRING(@temp_to_pos, 1, @comma_idx - 1)))
          
          IF LEN(@single_pos) > 0
          BEGIN
              SET @ChuteQty = @ChuteQty + 1              
              /* 转换单个 WCS 格口为 PLC 识别格式 */
              SET @single_plc_pos = dbo.f_tools_WcsToPlc(@single_pos)
              
              /* 拼接到格口集合 (每个格口占用 2 Bytes = 4个十六进制字符)[cite: 3] */
              SET @Chutes_Hex = @Chutes_Hex + RIGHT('0000' + dbo.f_tools_inttohex(CAST(@single_plc_pos AS INT)), 4)
          END
          
          /* 剔除已处理部分 */
          SET @temp_to_pos = SUBSTRING(@temp_to_pos, @comma_idx + 1, LEN(@temp_to_pos))
      END

      /* --- 2. 小报文总长度计算 --- */
      /* 固定部分32字节 + (格口数量 * 2字节) + 条码长度[cite: 3] */
      SET @msg_len = 32 + (@ChuteQty * 2) + @barcode_len

      /* --- 3. 组装 0x08 报文 (严格遵循 v8.1 SDS->PLC 地址回复格式) --- */
      SET @v_Msg = 
            'FCFC'                                                              + /* 0~1: 起始符[cite: 3] */
            '08'                                                                + /* 2: 报文编码[cite: 3] */
            '00'                                                                + /* 3: ACK状态 (0:无需确认)[cite: 3] */
            RIGHT('0000' + dbo.f_tools_inttohex(@msg_len), 4)                   + /* 4~5: 小报文长度 (2B)[cite: 3] */
            '00000000'                                                          + /* 6~9: ACK序号 (4B)[cite: 3] */
            '0000'                                                              + /* 10~11: 小车号 (2B) - 暂补0[cite: 3] */
            @ParcelID                                                           + /* 12~15: 包裹号 (4B)[cite: 3] */
            '0000'                                                              + /* 16~17: 上包台号 (2B) - 暂补0[cite: 3] */
            RIGHT('0000' + dbo.f_tools_inttohex(CAST(ISNULL(@bcr_no, '0') AS INT)), 4) + /* 18~19: 读码器 (2B) - 使用传入参数[cite: 3] */
            '0000'                                                              + /* 20~21: 备用字段 (2B)[cite: 3] */
            RIGHT('0000' + dbo.f_tools_inttohex(@barcode_len), 4)               + /* 22~23: 条码长度 (2B)[cite: 3] */
            DBO.f_tools_HEX(@barcode)                                           + /* 24~x: 条码内容[cite: 3] */
            RIGHT('0000' + dbo.f_tools_inttohex(CAST(ISNULL(@label, '0') AS INT)), 4) + /* 24+x: 是否贴标 (2B)[cite: 3] */
            '0000'                                                              + /* 26+x: 设备编号 (2B) - 默认0[cite: 3] */
            RIGHT('0000' + dbo.f_tools_inttohex(@ChuteQty), 4)                  + /* 28+x: 格口数量 (2B)[cite: 3] */
            @Chutes_Hex                                                         + /* 30+x: 目标格口 (动态n字节)[cite: 3] */
            'FDFD'                                                                /* 结尾符[cite: 3] */

      EXEC sp_plc_pack_nr @NEW_REQ_NO OUT;
      
      /* --- 4. 大报文总长度计算 --- */
      /* 大报文头(26字节) + 小报文长度 + 大报文尾(4字节) = 30 + @msg_len[cite: 3] */
      SET @total_pack_len = 30 + @msg_len

      /* --- 5. 组装大报文包 (严格遵循 v8.1 数据头格式) --- */
      SET @v_PACK = 
            'FEFEFEFE'                                                          + /* 0~3: 起始符 (4B)[cite: 3] */
            RIGHT('00000000' + dbo.f_tools_inttohex(@NEW_REQ_NO), 8)            + /* 4~7: 数据包序号 (4B)[cite: 3] */
            '0000'                                                              + /* 8~9: 备用字段 (2B)[cite: 3] */
            RIGHT('0000' + dbo.f_tools_inttohex(@total_pack_len), 4)            + /* 10~11: 大报文总长度 (2B)[cite: 3] */
            '00000000'                                                          + /* 12~15: ACK确认数据包序号 (4B)[cite: 3] */
            '0000'                                                              + /* 16~17: ACK状态 (2B)[cite: 3] */
            dbo.f_plc_TimeStamp()                                               + /* 18~25: 时间戳 (8B)[cite: 3] */
            @v_Msg                                                              + /* 26~x: 小报文信息[cite: 3] */
            'FFFFFFFF'                                                            /* 结尾符 (4B)[cite: 3] */
      
      SET @p_send = @dvc_no + '&=' + @v_PACK
  end 
  
END



GO

