DROP PROCEDURE [sp_plc_msg_send]
GO

CREATE PROCEDURE [sp_plc_msg_send]
  @P_dvc_no VARCHAR(20), 
	@p_send VARCHAR(4000) OUT, 
   @P_CODE VARCHAR(100) OUT,
   @p_CMD_NAME VARCHAR(2000) out
AS
DECLARE @v_hand_cmd_id VARCHAR(100);
DECLARE @V_CMD_NAME VARCHAR(4000);
DECLARE @V_CMD VARCHAR(4000);
declare @V_LMSG_TIME VARCHAR(100);
DECLARE
  @V_heartbeat VARCHAR(4000),
  @v_DATE1     DATETIME = GETDATE(),
  @v_s         INT = 0,
  @NAME        VARCHAR(4000),
  @CMD_NAME        VARCHAR(4000) = '' ;

BEGIN
  SELECT   TOP 1
           @v_hand_cmd_id = a.id, @V_CMD_NAME    = A.CMD_NAME, @V_CMD         = A.CMD
  FROM     wcs_tools_hand_cmd A
  WHERE    A.DVC_NO = @P_dvc_no
  ORDER BY a.id

  IF @@ROWCOUNT = 1
    BEGIN
      SET @p_send     = @V_CMD
      SET @p_CMD_NAME = @V_CMD_NAME

      /*执行完了就删除*/
      DELETE FROM wcs_tools_hand_cmd
      WHERE       id = @V_HAND_CMD_ID

      /*SET @p_send=dbo.VarCharToHex(@p_send); */

      SET @v_s        = DATEDIFF(ms, @V_DATE1, GETDATE()) / 100

      SET @NAME       = 'PLC' + @P_dvc_no + '手动命令'
      
      SET @CMD_NAME = LEFT('wcs->plc:pos_type,107_post_type:', 17)
      
      if @CMD_NAME <> 'wcs->plc:pos_type'
      begin
	      EXEC [dbo].[sp_create_wcs_log]
		  	'lamp_send',                   /*1、作业名称 */
		  	NULL,                           /*2、容器号 */
		  	null,                           /*3、应去口 */
		  	NULL,                           /*4、实际口 */
			  NULL,                           /*5、读码器 */
			  NULL,                           /*6、分拣状态 */
			  @P_CODE,                        /*7、执行代码 */
		  	@V_CMD_NAME,                         /*8、执行信息 */
			  'SP_PLC_SEND_MSG',              /*9、执行过程 */
			  @v_s,                           /*10、执行时间 */
		  	@P_dvc_no,                      /*11、dvc编号 */  
		  	NULL,                           /*12、备用1 */
		  	NULL,                           /*13、备用2 */
		  	NULL,                           /*14、备用3 */
			  NULL,                           /*15、任务状态 */  
			  NULL,		                        /*16、上车状态 */
				null                            /*16、任务号 */
			end
    END
    
    /*向不同的plc发送，特殊情况用到
   if @P_dvc_no='plc1'
      set @p_send='plc2=333333'; */
      
   /*set @p_send='333333'; */
  /* set @p_CMD_NAME='test '+@p_send */
	
/*   set @p_send='34343434' */
END


GO

-- ----------------------------
-- Procedure structure for sp_plc_pack_nr
-- ----------------------------
DROP PROCEDURE [sp_plc_pack_nr]
GO

CREATE PROCEDURE [sp_plc_pack_nr] (@pack_nr INT OUT)
AS
BEGIN
    /* 利用单条 UPDATE 的排他锁保证高并发安全，同时分开赋值解决类型冲突 */
    UPDATE WCS_MEM_config
    SET 
        /* 1. 给输出变量赋值 (纯数字计算，直接赋给 INT 类型的 @pack_nr) */
        @pack_nr = CASE 
            WHEN MEM_ITEM_VALUE = '60000' THEN 1
            ELSE CAST(MEM_ITEM_VALUE AS INT) + 1 
        END,

        /* 2. 记录旧值 (右侧的 MEM_ITEM_VALUE 永远取的是更新前的数据) */
        MEM_ITEM_OLDVALUE = MEM_ITEM_VALUE,

        /* 3. 更新字段值 (将同样的计算结果，强制转回 VARCHAR 存入数据库表) */
        MEM_ITEM_VALUE = CAST(
            CASE 
                WHEN MEM_ITEM_VALUE = '60000' THEN 1
                ELSE CAST(MEM_ITEM_VALUE AS INT) + 1 
            END AS VARCHAR(50)
        )
    WHERE MEM_ITEM_NO = 'pack_nr_plc';
END



GO

