CREATE PROCEDURE [sp_sd_make_label_msg] 
	@shipment_id VARCHAR(4000),@cur_pos varchar(20),	
	@weight varchar(20),@length varchar(20),@width varchar(20),@height varchar(20),
	@receiver_name varchar(50),@sort_code varchar(50)
AS        
BEGIN
  select top 1 1 from wcs_tools_label 
	  where wms_to_pos=@cur_pos and receiver_name=''
  if @@rowcount=1
    update wcs_tools_label set receiver_name=@receiver_name,sort_code=@sort_code
		  ,parcel_num=parcel_num+1,last_parcel= @shipment_id,isPrinted='0' 
		  where wms_to_pos=@cur_pos 
	else
	  update wcs_tools_label set parcel_num=parcel_num+1 
		  where wms_to_pos=@cur_pos  
	INSERT INTO wcs_tools_label_detail( wms_to_pos,flag,barcode,weight,length,width,height) 
	  VALUES (@cur_pos,'0',@shipment_id,@weight,@length,@width,@height) 
	 
END

