-- ----------------------------
-- Procedure structure for sp_sd_pack_nr
-- ----------------------------
DROP PROCEDURE [sp_sd_pack_nr]
GO

CREATE PROCEDURE [sp_sd_pack_nr](@pack_nr INT OUT)
AS
BEGIN	
	 /* 利用单条 UPDATE 的排他锁保证高并发安全，同时分开赋值解决类型冲突 */
    UPDATE WCS_MEM_config
    SET 
        /* 1. 给输出变量赋值 (纯数字计算，直接赋给 INT 类型的 @pack_nr) */
        @pack_nr = CASE 
            WHEN MEM_ITEM_VALUE = '60000' THEN 1
            ELSE CAST(MEM_ITEM_VALUE AS INT) + 1 
        END,

        /* 2. 记录旧值 (右侧的 MEM_ITEM_VALUE 永远取的是更新前的数据) */
        MEM_ITEM_OLDVALUE = MEM_ITEM_VALUE,

        /* 3. 更新字段值 (将同样的计算结果，强制转回 VARCHAR 存入数据库表) */
        MEM_ITEM_VALUE = CAST(
            CASE 
                WHEN MEM_ITEM_VALUE = '60000' THEN 1
                ELSE CAST(MEM_ITEM_VALUE AS INT) + 1 
            END AS VARCHAR(50)
        )
    WHERE MEM_ITEM_NO = 'pack_nr_sd';
END


GO

-- ----------------------------
-- Procedure structure for sp_sd_report_induction
-- ----------------------------
DROP PROCEDURE [sp_sd_report_induction]
GO
CREATE PROCEDURE [sp_sd_report_induction] 
  @p_dvc_id VARCHAR(50),  /*plc编号*/
  @p_REV VARCHAR(4000) , 
  @p_CODE VARCHAR(20) OUT,
  @p_MSG VARCHAR(400) OUT
AS
DECLARE @State VARCHAR(20), @Spare VARCHAR(20)
       ,@BARCODE VARCHAR(500), @type VARCHAR(50)
       ,@BCR_NO VARCHAR(10), @barcode_len int
       ,@TrackID VARCHAR(20), @ParcelID VARCHAR(20), @Induction VARCHAR(20), @Occupied VARCHAR(20)
DECLARE @v_s INT = 0, @v_DATE1 DATETIME = GETDATE()
DECLARE @offset INT /* 用于计算条码后面动态字段的十六进制字符偏移量 */

BEGIN
  SET @p_code = '0'

  BEGIN TRY
    /* 1. 解析条码之前的固定位置字段 (v8.1 协议) */
    SET @TrackID     = CAST(dbo.f_tools_hextoint(SUBSTRING(@p_REV, 21, 4)) AS VARCHAR)  /* 小车号 (10~11字节) */
    SET @ParcelID    = CAST(dbo.f_tools_hextoint(SUBSTRING(@p_REV, 25, 8)) AS VARCHAR)  /* 包裹号 (12~15字节) */
    SET @Induction   = CAST(dbo.f_tools_hextoint(SUBSTRING(@p_REV, 33, 4)) AS VARCHAR)  /* 上包台号 (16~17字节) */
    SET @BCR_NO      = CAST(dbo.f_tools_hextoint(SUBSTRING(@p_REV, 37, 4)) AS VARCHAR)  /* 读码器 (18~19字节) */
    SET @Occupied    = CAST(dbo.f_tools_hextoint(SUBSTRING(@p_REV, 41, 4)) AS VARCHAR)  /* 占用小车数量 (20~21字节) */
    SET @barcode_len = dbo.f_tools_hextoint(SUBSTRING(@p_REV, 45, 4))                   /* 条码长度 (22~23字节) */
    
    /* 2. 解析动态长度的条码 */
    /* 从第 49 个字符(第24字节)开始截取，长度为 barcode_len * 2 */
   /* SET @BARCODE     = RTRIM(dbo.f_tools_Hex_To_Char(REPLACE(SUBSTRING(@p_rev, 49, @barcode_len*2), '00', '')))  */
    SET @BARCODE = dbo.f_tools_HEX_TO_CHAR(SUBSTRING(@p_REV, 49, @barcode_len * 2))

    /* 3. 解析条码之后的动态位置字段 (4.2.1.1 规范) */
    /* 动态起点 = 条码起点(49) + 条码所占字符数(@barcode_len*2) */
    SET @offset = 49 + @barcode_len * 2
    
    /* 状态: 0.上车成功 3.预上车请求 9.上车失败 */
    SET @State       = CAST(dbo.f_tools_hextoint(SUBSTRING(@p_REV, @offset, 4)) AS VARCHAR) 
    /* 备用: 6字节 (12个十六进制字符) */
    SET @Spare       = SUBSTRING(@p_REV, @offset + 4, 12) 
        
    UPDATE wcs_task 
      SET /*track_id = @TrackID, */
        update_date = GETDATE() 
      WHERE barcode = @BARCODE AND task_type = 'cv'
      
    SET @p_Msg = 
          '[sd_report_induction]' + @BARCODE 
          + isnull(@p_MSG,'')
          + '__State:' + isnull(@State, '')  /* 0:成功, 3:预上车, 9:失败 */
          + ';TrackID:' + isnull(@TrackID, '')
          + ';ParcelID:' + isnull(@ParcelID, '')
          + ';Induction:' + isnull(@Induction, '')
          + ';Occupied:' + isnull(@Occupied, '')
          + ';' + CAST(@p_dvc_id AS VARCHAR)                                                                             
  END TRY
  BEGIN CATCH
    SELECT @p_code = ERROR_NUMBER(), @p_msg  = '上车报告异常：' + ERROR_MESSAGE()
  END CATCH

  SET @v_s = DATEDIFF(ms, @V_DATE1, GETDATE()) / 100
  SET @p_msg = isnull(@p_msg,'') + ',work_sec:' + CAST(@v_s AS VARCHAR(10))
  
  EXEC [dbo].[sp_create_wcs_log]
    'sd_report_induction',                        /*1、作业名称 */
    @BARCODE,                     /*2、容器号 */
    NULL,                         /*3、应去口 */
    @Induction,                   /*4、实际口(上车报告用上包台代替展示) */
    @BCR_NO,                      /*5、读码器 */
    null,                       /*6、状态 (0上车成功 3预上车 9上车失败) */
    @P_CODE,                      /*7、执行代码 */
    @p_msg,                       /*8、执行信息 */
    'sp_sd_report_induction',     /*9、执行过程 */
    @v_s,                         /*10、执行时间 */
    @P_dvc_id,                    /*11、dvc编号 */  
    @p_REV,                       /*12、备用1 */
    NULL,                         /*13、备用2 */
    NULL,                         /*14、备用3 */
    null,                         /*15、任务状态 */  
    @State,                         /*16、上车状态 */ 
    NULL                          /*17、任务号 */                       
END

GO

-- ----------------------------
-- Procedure structure for sp_sd_report_sort
-- ----------------------------
DROP PROCEDURE [sp_sd_report_sort]
GO
CREATE PROCEDURE [sp_sd_report_sort] 
  @p_dvc_id VARCHAR(50),  /*plc编号*/
  @p_REV VARCHAR(4000) , 
  @p_CODE VARCHAR(20) OUT,
  @p_MSG VARCHAR(400) OUT
AS
DECLARE @SortState VARCHAR(20),@SortState_Msg VARCHAR(20),@AllocDest VARCHAR(20),@ExecuteDest VARCHAR(20)
       ,@Spare VARCHAR(20),@BARCODE VARCHAR(500),@CUR_POS VARCHAR(50)
       ,@wms_to_pos VARCHAR(20) = '',@type VARCHAR(50),@BCR_NO VARCHAR(10),@barcode_len int
       ,@scan_id varchar(100)
       ,@TrackID VARCHAR(20), @ParcelID VARCHAR(20), @Induction VARCHAR(20), @Occupied VARCHAR(20) /* 新增v8.1提取变量 */
DECLARE @v_s INT = 0,@v_DATE1 DATETIME = GETDATE()
DECLARE @offset INT /* 用于计算条码后面动态字段的十六进制字符偏移量 */
declare @weight varchar(20),@volume varchar(20),@length varchar(20),@width varchar(20),@height varchar(20)
BEGIN
  SET @p_code = '0'

  BEGIN TRY
    /* 1. 解析条码之前的固定位置字段 (完全适配 v8.1 协议) */
    SET @TrackID     = CAST(dbo.f_tools_hextoint(SUBSTRING(@p_REV, 21, 4)) AS VARCHAR)  /* 小车号 (10~11字节) */
    SET @ParcelID    = CAST(dbo.f_tools_hextoint(SUBSTRING(@p_REV, 25, 8)) AS VARCHAR)  /* 包裹号 (12~15字节) */
    SET @Induction   = CAST(dbo.f_tools_hextoint(SUBSTRING(@p_REV, 33, 4)) AS VARCHAR)  /* 上包台号 (16~17字节) */
    SET @BCR_NO      = CAST(dbo.f_tools_hextoint(SUBSTRING(@p_REV, 37, 4)) AS VARCHAR)  /* 读码器 (18~19字节) */
    SET @Occupied    = CAST(dbo.f_tools_hextoint(SUBSTRING(@p_REV, 41, 4)) AS VARCHAR)  /* 占用小车数量 (20~21字节) */
    SET @barcode_len = dbo.f_tools_hextoint(SUBSTRING(@p_REV, 45, 4))                   /* 条码长度 (22~23字节) */
    
    /* 2. 解析动态长度的条码 */
    /* 从第 49 个字符(第24字节)开始截取，长度为 barcode_len * 2 */
    /*SET @BARCODE     = RTRIM(dbo.f_tools_Hex_To_Char(REPLACE(SUBSTRING(@p_rev, 49, @barcode_len*2), '00', '')))  */
    SET @BARCODE     = dbo.f_tools_HEX_TO_CHAR(SUBSTRING(@p_REV, 49, @barcode_len * 2))

    /* 3. 解析条码之后的动态位置字段 */
    /* 动态起点 = 条码起点(49) + 条码所占字符数(@barcode_len*2) */
    SET @offset = 49 + @barcode_len * 2
    
    SET @SortState   = CAST(dbo.f_tools_hextoint(SUBSTRING(@p_REV, @offset, 4)) AS VARCHAR)      /* 分拣状态: 0为成功，其他为异常 */
    SET @AllocDest   = CAST(dbo.f_tools_hextoint(SUBSTRING(@p_REV, @offset + 4, 4)) AS VARCHAR)  /* 分配地址 */
    SET @ExecuteDest = CAST(dbo.f_tools_hextoint(SUBSTRING(@p_REV, @offset + 8, 4)) AS VARCHAR)  /* 执行地址 */
    SET @Spare       = CAST(dbo.f_tools_hextoint(SUBSTRING(@p_REV, @offset + 12, 4)) AS VARCHAR) /* 备用字段(原版本为异常原因, v8.1后已改) */

    SET @type        = 'sd_report'
    SET @CUR_POS     = dbo.f_tools_PlcToWcs(@ExecuteDest);
        
    IF isnull(@CUR_POS,'') <> ''  
    BEGIN   
      --UPDATE wcs_task SET cur_pos=@CUR_POS, update_date = GETDATE() WHERE barcode=@BARCODE AND task_type='cv'   /*更新当前口 */
      /*select top 1 @scan_id=scan_id from wcs_task WHERE barcode=@BARCODE AND task_type='cv' */
      /*if isnull(@scan_id,'')<>'' */
       /* INSERT INTO wcs_tools_feedback(type,flag,curAddress,scan_id,sort_time)  */
         /* VALUES ('sort',0,@CUR_POS,@scan_id,GETDATE()) */
      
      SET @p_Msg = 
          '[sd_report]' + @BARCODE 
          + ',cur_pos:' + isnull(@CUR_POS,'') + '(' + isnull(@ExecuteDest,'') + ')' 
          + isnull(@p_MSG,'')
          + '__SortState:' + isnull(@SortState, '')
          + ';AllocDest:' + isnull(@AllocDest, '')
          + ';ExecuteDest:' + isnull(@ExecuteDest, '')
          + ';TrackID:' + isnull(@TrackID, '')
          + ';ParcelID:' + isnull(@ParcelID, '')
          + ';Induction:' + isnull(@Induction, '')
          + ';Occupied:' + isnull(@Occupied, '')
          + ';' + CAST(@p_dvc_id AS VARCHAR)    
    END 
    ELSE
    BEGIN
      /*转向口*/
      SET @p_Msg =
          'sd_report_turning:' 
          + isnull(@CUR_POS, '') + '[' + isnull(@ExecuteDest, '') + '] OR  ' + isnull(@wms_to_pos, '')
          + '[' + isnull(@AllocDest, '') + ']' + 'no pos,barcode：' + @BARCODE 
          + '__SortState:' + isnull(@SortState, '')
          + ';AllocDest:' + isnull(@AllocDest, '')
          + ';ExecuteDest:' + isnull(@ExecuteDest, '') 
          + ';TrackID:' + isnull(@TrackID, '') 
          + ';ParcelID:' + isnull(@ParcelID, '')
          + ';Induction:' + isnull(@Induction, '')
          + ';Occupied:' + isnull(@Occupied, '')
          + ';' + CAST(@p_dvc_id AS VARCHAR)  
    END                                                                          
  END TRY
  BEGIN CATCH
    SELECT @p_code = ERROR_NUMBER(), @p_msg  = '分拣报告：' + ERROR_MESSAGE()
  END CATCH

  SET @v_s = DATEDIFF(ms, @V_DATE1, GETDATE()) / 100
  SET @p_msg = isnull(@p_msg,'') + ',work_sec:' + CAST(@v_s AS VARCHAR(10))
  
  EXEC [dbo].[sp_create_wcs_log]
    @type,                        /*1、作业名称 */
    @BARCODE,                     /*2、容器号 */
    NULL,                         /*3、应去口 */
    @CUR_POS,                     /*4、实际口 */
    @BCR_NO,                      /*5、读码器 */
    @SortState,                   /*6、分拣状态 (记录结果及异常原因) */
    @P_CODE,                      /*7、执行代码 */
    @p_msg,                       /*8、执行信息 */
    'sp_sd_report_sort',          /*9、执行过程 */
    @v_s,                         /*10、执行时间 */
    @P_dvc_id,                    /*11、dvc编号 */  
    @p_REV,                       /*12、备用1 */
    NULL,                         /*13、备用2 */
    NULL,                         /*14、备用3 */
    NULL,                         /*15、任务状态 */  
    NULL,                         /*16、上车状态 */ 
    NULL                          /*17、wcs任务号 */                       
END

GO

-- ----------------------------
-- Procedure structure for sp_sd_report_sort_confirm
-- ----------------------------
DROP PROCEDURE [sp_sd_report_sort_confirm]
GO
CREATE PROCEDURE [sp_sd_report_sort_confirm] 
  @p_dvc_id VARCHAR(50),  /*plc编号*/
  @p_REV VARCHAR(4000) , 
  @p_CODE VARCHAR(20) OUT,
  @p_MSG VARCHAR(400) OUT
AS
DECLARE @SortState VARCHAR(20),@SortState_Msg VARCHAR(20),@AllocDest VARCHAR(20),@ExecuteDest VARCHAR(20)
       ,@Spare VARCHAR(20),@BARCODE VARCHAR(500),@CUR_POS VARCHAR(50)
       ,@wms_to_pos VARCHAR(20) = '',@type VARCHAR(50),@BCR_NO VARCHAR(10),@barcode_len int
       ,@shipment_id varchar(100)
       ,@TrackID VARCHAR(20), @ParcelID VARCHAR(20), @Induction VARCHAR(20), @Occupied VARCHAR(20) /* 新增v8.1提取变量 */
DECLARE @v_s INT = 0,@v_DATE1 DATETIME = GETDATE()
DECLARE @offset INT /* 用于计算条码后面动态字段的十六进制字符偏移量 */
declare @weight varchar(20),@volume varchar(20),@length varchar(20),@width varchar(20),@height varchar(20),@status_trk varchar(20),@status_log varchar(20)
declare @sort_code varchar(100),@receiver_name varchar(100)
BEGIN
  SET @p_code = '0'
  set @p_msg=''

  BEGIN TRY
    /* 1. 解析条码之前的固定位置字段 (完全适配 v8.1 协议) */
    SET @TrackID     = CAST(dbo.f_tools_hextoint(SUBSTRING(@p_REV, 21, 4)) AS VARCHAR)  /* 小车号 (10~11字节) */
    SET @ParcelID    = CAST(dbo.f_tools_hextoint(SUBSTRING(@p_REV, 25, 8)) AS VARCHAR)  /* 包裹号 (12~15字节) */
    SET @Induction   = CAST(dbo.f_tools_hextoint(SUBSTRING(@p_REV, 33, 4)) AS VARCHAR)  /* 上包台号 (16~17字节) */
    SET @BCR_NO      = CAST(dbo.f_tools_hextoint(SUBSTRING(@p_REV, 37, 4)) AS VARCHAR)  /* 读码器 (18~19字节) */
    SET @Occupied    = CAST(dbo.f_tools_hextoint(SUBSTRING(@p_REV, 41, 4)) AS VARCHAR)  /* 占用小车数量 (20~21字节) */
    SET @barcode_len = dbo.f_tools_hextoint(SUBSTRING(@p_REV, 45, 4))                   /* 条码长度 (22~23字节) */
    
    /* 2. 解析动态长度的条码 */
    /* 从第 49 个字符(第24字节)开始截取，长度为 barcode_len * 2 */
    SET @BARCODE     = dbo.f_tools_HEX_TO_CHAR(SUBSTRING(@p_REV, 49, @barcode_len * 2))

    /* 3. 解析条码之后的动态位置字段 */
    /* 动态起点 = 条码起点(49) + 条码所占字符数(@barcode_len*2) */
    SET @offset = 49 + @barcode_len * 2
    
    SET @SortState   = CAST(dbo.f_tools_hextoint(SUBSTRING(@p_REV, @offset, 4)) AS VARCHAR)      /* 分拣状态: 0为成功，其他为异常 */
    SET @AllocDest   = CAST(dbo.f_tools_hextoint(SUBSTRING(@p_REV, @offset + 4, 4)) AS VARCHAR)  /* 分配地址 */
    SET @ExecuteDest = CAST(dbo.f_tools_hextoint(SUBSTRING(@p_REV, @offset + 8, 4)) AS VARCHAR)  /* 执行地址 */
    SET @Spare       = CAST(dbo.f_tools_hextoint(SUBSTRING(@p_REV, @offset + 12, 4)) AS VARCHAR) /* 备用字段(原版本为异常原因, v8.1后已改) */

    SET @type        = 'sd_report_confirm'   																																	 
        
    IF isnull(@ExecuteDest,'') <> ''  
    BEGIN   
      select top 1 @CUR_POS=to_pos,@shipment_id=shipment_id,@receiver_name=receiver_name,@sort_code=sort_code,@status_trk=status 	 
			from wcs_task WHERE barcode=@BARCODE AND task_type='cv' and plc_to_pos=@ExecuteDest order by to_pos asc 
			if @@rowcount =1 
				exec sp_sd_make_label_msg @shipment_id,@CUR_POS,@weight,@length,@width,@height,@receiver_name,@sort_code					
    
      UPDATE wcs_task SET cur_pos=@CUR_POS, update_date = GETDATE() WHERE barcode=@BARCODE AND task_type='cv'   /*更新当前口 */
      
      if isnull(@barcode,'') in ('Noread','??????????','Noread????') 
		  set @status_log='101'
		  else
		  begin
		    if isnull(@status_trk,'')<>'' 
			    set @status_log= @status_trk 	
		    else	
		      set @status_log=@SortState	
	    end
      
      if @ExecuteDest = dbo.f_tools_mem('bcr_no_'+'1001')	
        INSERT INTO wcs_tools_feedback(type,flag,curAddress,shipment_id,sort_time,barcode,status) 
          VALUES ('sort_err',0,@ExecuteDest,@shipment_id,GETDATE(),@barcode,@status_log)
      else      
        INSERT INTO wcs_tools_feedback(type,flag,curAddress,shipment_id,sort_time,barcode) 
          VALUES ('sort',0,@CUR_POS,@shipment_id,GETDATE(),@barcode)
      
      SET @p_Msg = 
          '[sd_report_confirm]' + @BARCODE 
          + ',cur_pos:' + isnull(@CUR_POS,'') + '(' + isnull(@ExecuteDest,'') + ')' 
          + isnull(@p_MSG,'')
          + '__SortState:' + isnull(@SortState, '')
          + ';AllocDest:' + isnull(@AllocDest, '')
          + ';ExecuteDest:' + isnull(@ExecuteDest, '')
          + ';TrackID:' + isnull(@TrackID, '')
          + ';ParcelID:' + isnull(@ParcelID, '')
          + ';Induction:' + isnull(@Induction, '')
          + ';Occupied:' + isnull(@Occupied, '')
          + ';' + CAST(@p_dvc_id AS VARCHAR)    
    END 
    ELSE
    BEGIN
      /*转向口*/
      SET @p_Msg =
          'sd_report_turning_confirm:' 
          + isnull(@CUR_POS, '') + '[' + isnull(@ExecuteDest, '') + '] OR  ' + isnull(@wms_to_pos, '')
          + '[' + isnull(@AllocDest, '') + ']' + 'no pos,barcode：' + @BARCODE 
          + '__SortState:' + isnull(@SortState, '')
          + ';AllocDest:' + isnull(@AllocDest, '')
          + ';ExecuteDest:' + isnull(@ExecuteDest, '') 
          + ';TrackID:' + isnull(@TrackID, '') 
          + ';ParcelID:' + isnull(@ParcelID, '')
          + ';Induction:' + isnull(@Induction, '')
          + ';Occupied:' + isnull(@Occupied, '')
          + ';' + CAST(@p_dvc_id AS VARCHAR)  
    END 
		                                                                         
  END TRY
  BEGIN CATCH
    SELECT @p_code = ERROR_NUMBER(), @p_msg  = '分拣确认：' + ERROR_MESSAGE()
  END CATCH

  SET @v_s = DATEDIFF(ms, @V_DATE1, GETDATE()) / 100
  SET @p_msg = isnull(@p_msg,'') + ',work_sec:' + CAST(@v_s AS VARCHAR(10))
  
  EXEC [dbo].[sp_create_wcs_log]
    @type,                        /*1、作业名称 */
    @BARCODE,                     /*2、容器号 */
    NULL,                         /*3、应去口 */
    @CUR_POS,                     /*4、实际口 */
    @BCR_NO,                      /*5、读码器 */
    @SortState,                   /*6、分拣状态 (记录结果及异常原因) */
    @P_CODE,                      /*7、执行代码 */
    @p_msg,                       /*8、执行信息 */
    'sp_sd_report_sort_confirm',          /*9、执行过程 */
    @v_s,                         /*10、执行时间 */
    @P_dvc_id,                    /*11、dvc编号 */  
    @p_REV,                       /*12、备用1 */
    NULL,                         /*13、备用2 */
    NULL,                         /*14、备用3 */
    @status_log,                         /*15、任务状态 */  
    NULL,                         /*16、上车状态 */ 
    @shipment_id                          /*17、任务号 */                       
END

GO

-- ----------------------------
-- Procedure structure for sp_sd_request_dest
-- ----------------------------
DROP PROCEDURE [sp_sd_request_dest]
GO
CREATE PROCEDURE [sp_sd_request_dest] 
  @P_dvc_id VARCHAR(20), @P_REV VARCHAR(4000), @P_SEND VARCHAR(4000) OUT, @P_CODE VARCHAR(10) OUT, @P_MSG VARCHAR(4000) OUT
AS
DECLARE @Tel_Head VARCHAR(10) = 'FCFC',/*小包起始符（FCFC）*/@Tel_End VARCHAR(10) = 'FDFD'  /*小包结束符（FDFD）*/
DECLARE @Barcode VARCHAR(500),@Destination01 VARCHAR(50),@BCR_NO VARCHAR(10)
DECLARE @TO_POS VARCHAR(50),@NO_EXCEPTION_NO VARCHAR(20),@ERR_EXCEPTION_NO VARCHAR(20)
DECLARE @v_s INT = 0,@v_DATE1 DATETIME = GETDATE()
DECLARE @barcode_len int,@v_msg varchar(4000)/*hc的报文 */
DECLARE @ParcelID int, @TrackID int,@Induction int

declare @weight int,@width int,@length int,@height int,@volume int,
  @send varchar(4000),@send2 varchar(4000),@url varchar(1000),
  @tel_sn varchar(20),@DestAmount int,@DestArr varchar(200), @tel_length int  
declare @id1 varchar(200),@pos2 varchar(50),@url_len int
BEGIN
  SET @P_SEND = ''
  SET @P_CODE = '0'
  SET @P_MSG  = ''

  BEGIN TRY
/* 1. 小报文长度 (2 Bytes: Byte 4) */
    SET @tel_sn = SUBSTRING(@p_REV, 9, 4)   
/* 2. 包裹号 (4 Bytes: Byte 12)  <- 修正: 原为 17,4，应为 25,8 */
    SET @ParcelID = dbo.f_tools_hextoint(SUBSTRING(@p_REV, 25, 8))
/* 3. 读码器 (2 Bytes: Byte 18)  <- 修正: 原为 21,4，应为 37,4 */
    SET @BCR_NO = CAST(dbo.f_tools_hextoint(SUBSTRING(@p_REV, 37, 4)) AS VARCHAR)
/* 4. 条码长度 (2 Bytes: Byte 22) <- 修正: 原为 25,4，应为 45,4 */
    SET @barcode_len = dbo.f_tools_hextoint(SUBSTRING(@p_REV, 45, 4))
/* 5. 条码内容 (x Bytes: Byte 24) <- 修正: 起始索引应为 49 */
    SET @Barcode = dbo.f_tools_HEX_TO_CHAR(SUBSTRING(@p_REV, 49, @barcode_len * 2))
/* 6. 货物长度 (2 Bytes: Byte 28+x) <- 修正: 起始索引应为 57 + len*2 */
    SET @length = dbo.f_tools_hextoint(SUBSTRING(@p_REV, 57 + @barcode_len * 2, 4)) 
/* 7. 货物宽度 (2 Bytes: Byte 30+x) <- 修正: 起始索引应为 61 + len*2 */
    SET @width = dbo.f_tools_hextoint(SUBSTRING(@p_REV, 61 + @barcode_len * 2, 4)) 
/* 8. 货物高度 (2 Bytes: Byte 32+x) <- 修正: 起始索引应为 65 + len*2 */
    SET @height = dbo.f_tools_hextoint(SUBSTRING(@p_REV, 65 + @barcode_len * 2, 4))
/* 9. 货物重量 (2 Bytes) <- 改为截取 4 个十六进制字符 */
    SET @weight = dbo.f_tools_hextoint(SUBSTRING(@p_REV, 69 + @barcode_len * 2, 4))
/* 10. 存图地址长度值 (2 Bytes) <- 紧跟重量之后，截取 4 个十六进制字符 */
    SET @url_len = dbo.f_tools_hextoint(SUBSTRING(@p_REV, 73 + @barcode_len * 2, 4))
/* 11. 存图地址字符 (N Bytes) <- 根据上一步算出的长度动态截取并转换为ASCII字符串 */    
    SET @url = dbo.f_tools_HEX_TO_CHAR(SUBSTRING(@p_REV, 77 + @barcode_len * 2, @url_len * 2)) 
	 /*12 track_id */
		SET @TrackID = dbo.f_tools_hextoint(SUBSTRING(@p_REV, 21, 4))      
	 /*13 Induction */
		SET @Induction = dbo.f_tools_hextoint(SUBSTRING(@p_REV, 33, 4)) 
				
		INSERT INTO wcs_tools_feedback( type,flag,barcode,sort_time)
      VALUES ('scan','0',REPLACE(@barcode, CHAR(5), ','),getdate())							 	 																				

		/*查询扫码器配置表中该扫码器是否为实时请求扫码器,hc1四面扫 hc2换箱  hc3容器申请   hc4任务取消  hc5重量上报  hc6任务分流  0代表非实时请求  7接力拣选*/
		IF isnull(dbo.f_tools_mem('bcr_type_'+@BCR_NO),'') in ('6') 
		  AND  @Barcode NOT IN ('','??????????', 'NoRead','NG','!!!!!','??????') 
			and isnull(dbo.f_tools_mem('sort_mode'),'') in ('1')
		BEGIN	
		  /*一层任务分流																		 								   */
			SET @p_msg = isnull(@Barcode ,'') + ',post wms'																				 								 																		 																																																															 		 					 
			exec sp_plc_make_wms_msg '6',@Barcode,@weight,@length,@width,@height,@send out
			set @p_send= '~~hc46&='+@send 																																																																																														 								 																		 																																																															 		 					 
																																																																																																																																																																																																	 																																																																																																 								 																		 																																																															 		 					 
    	DELETE FROM wcs_tools_parcel	WHERE ParcelID=@ParcelID	AND	type='cv'											 																										          
			INSERT INTO wcs_tools_parcel(barcode,type,status,ParcelID,TrackID,Induction,msg,bcr,dvc_no,tel_sn,url) 
			  VALUES (@Barcode,'cv','0',@ParcelID,@TrackID,@Induction,isnull(@send,''),@BCR_NO,@P_dvc_id,@tel_sn,@url)	
		END
		else
		begin		
			/*非实时请求 */
		  set @NO_EXCEPTION_NO=	dbo.f_tools_mem('bcr_no_'+@BCR_NO)
			set @ERR_EXCEPTION_NO= dbo.f_tools_mem('bcr_err_'+@BCR_NO)				    	

	  	IF @Barcode IN ('','??????????', 'NoRead','NG','!!!!!') 
	    BEGIN
		    SET @TO_POS = @ERR_EXCEPTION_NO
				set @barcode = 'NoRead'
		    SET @p_msg    = isnull(@barcode,'')+',ToPos:'
				
				INSERT INTO wcs_task( barcode,to_pos,task_type,shipment_id,url,status) 
				  values(@barcode,@to_pos,'cv','',@url,'') 	
  	  END
	    ELSE
	    BEGIN
			  update wcs_task set ParcelID= @ParcelID where barcode=@Barcode and task_type='offline'
							 					  
			  SELECT top 1 @TO_POS = TO_POS
			  FROM wcs_task WHERE barcode=@Barcode and task_type='offline'

	  	 	IF @@rowcount = 1
	    	BEGIN 				  																			 		 							 											 			 																																																																																																																																																																																																																																																																																																																																																			 			      
			    SET @p_Msg = isnull(@Barcode,'')+',ToPos:'
		    END
	    	ELSE
	  	 	BEGIN
			 	  SET @p_msg    = isnull(@Barcode,'')+',NoTask,ToPos:'
			 	  SET @TO_POS = @NO_EXCEPTION_NO
	    	END
	    end      										 																																								 																																			
	    		 		 					    
			exec sp_sd_make_msg	'08',@P_dvc_id ,@barcode,@to_pos,'0',@BCR_NO,@ParcelID,@trackId,@Induction,@P_SEND out  				 														       	
		END	
		
		SET @p_msg ='[sd_request]' + isnull(@p_msg,'') + ISNULL(@to_pos,'') +'('+ isnull(dbo.f_tools_WcsToPlc(@to_pos),'') +')'
						+ ',Bcr' + @BCR_NO + ',length-width-height='+cast(@length as varchar)+'-'+cast(@width as varchar)+'-'+cast(@height as varchar)
						+ ',weight='++cast(@weight as varchar)+',url='+isnull(@url,'')
						+',ParcelID:' + cast(@ParcelID as varchar)		  	
		
  END TRY
  BEGIN CATCH
    SELECT @p_code = ERROR_NUMBER(), @p_msg  = '目的地请求错误：' + ERROR_MESSAGE()
  END CATCH

  SET @v_s    = DATEDIFF(ms, @V_DATE1, GETDATE()) / 100
  set @p_msg = isnull(@p_msg,'')+',work_sec:'+cast(@v_s as varchar(10))
  EXEC [dbo].[sp_create_wcs_log]
	  	'sd_request',              /*1、作业名称 */
	  	@Barcode,                     /*2、容器号 */
	  	null,                           /*3、应去口 */
	  	NULL,                           /*4、实际口 */
		  @BCR_NO,                      /*5、读码器 */
		  NULL,                           /*6、分拣状态 */
		  @P_CODE,                        /*7、执行代码 */
	  	@p_msg,                         /*8、执行信息 */
		  'SP_SD_REQUEST_DEST',          /*9、执行过程 */
		  @v_s,                           /*10、执行时间 */
	  	@P_dvc_id,                      /*11、dvc编号 */  
	  	@p_REV,                         /*12、备用1 */
	  	@P_SEND,                         /*13、备用2 */
	  	null,                           /*14、备用3 */
		  NULL,                           /*15、任务状态 */  
		  null,	                        /*16、上车状态 */
			null                           /*16、wcs任务号 */
END

GO

-- ----------------------------
-- Procedure structure for sp_tools_guide
-- ----------------------------
DROP PROCEDURE [sp_tools_guide]
GO

CREATE PROCEDURE [sp_tools_guide]
	@P_TO_POS VARCHAR(100),
	@P_BCR VARCHAR(50),
	@P_Destination VARCHAR(50) OUT
AS
	DECLARE @plc_to_pos VARCHAR(20) 
	DECLARE @v_err_EXCEPTION_NO VARCHAR(50)
	BEGIN
		SET @P_Destination = ''
		/*输送线转移口处理 */
		SELECT top 1 @plc_to_pos = plc_to_pos
		FROM   WCS_GUIDE_config
		WHERE  wcs_to_pos LIKE '%' + @P_TO_POS + '%'
					 AND GUIDE = @P_BCR
		
		IF @@rowcount = 1
		    SET @P_Destination = @plc_to_pos
		ELSE
		    SET @P_Destination = dbo.f_tools_WcsToPlc(@P_TO_POS)
					
		IF ISNULL(@P_Destination, '') = ''   /*如果格口为空则赋值异常口并转换为PLC格口 */
		BEGIN 
		/*  SET @P_Destination = @P_TO_POS */
			 set @v_err_EXCEPTION_NO= dbo.f_tools_mem('bcr_err_0'+@P_BCR)
			 SET @P_Destination = dbo.f_tools_WcsToPlc(@v_err_EXCEPTION_NO)
		 END 
		 
	END




GO

-- ----------------------------
-- Procedure structure for sp_tools_plan
-- ----------------------------
DROP PROCEDURE [sp_tools_plan]
GO

CREATE PROCEDURE [sp_tools_plan](   
    @logical_address  VARCHAR(10),	/*区域 */
	  @mode  varchar(10),/*模式*/
    @POS   VARCHAR(50) OUT
)
AS
	DECLARE @ID INT 
	BEGIN
		/*分拣策略，按数量分配,可配置出口数量 */
		SELECT @ID = MIN(id)
		FROM   wcs_plan_config
		WHERE  logical_address = @logical_address
		       /*AND TEMP1=@mode */
		       AND qty > qty_deal
					 AND  status = '1'
					-- AND WCS_TO_POS IN(SELECT WCS_TO_POS FROM wcs_pos_config WHERE stn_st='1')/*出货模式的站台均分 */
		
		IF @ID IS NULL
		BEGIN
		    SELECT @ID = MIN(id)
		    FROM   wcs_plan_config
		    WHERE  logical_address = @logical_address 
			    /*AND TEMP1=@mode */
			    AND qty<>0
					AND  status = '1'
				--AND WCS_TO_POS IN(SELECT WCS_TO_POS FROM wcs_pos_config WHERE stn_st='1')/*出货模式的站台均分 */
		    
				IF ISNULL(@ID,'')<>''
		      UPDATE wcs_plan_config
		      SET    qty_deal = 0
		      WHERE  logical_address = @logical_address 
		END     	
		
		UPDATE wcs_plan_config
		SET    qty_deal = qty_deal + 1
		WHERE  ID = @ID 
		
		SELECT @POS = WCS_TO_POS
		FROM   wcs_plan_config
		WHERE  ID = @id
	END




GO

-- ----------------------------
-- Procedure structure for sp_tts_ack_rev
-- ----------------------------
DROP PROCEDURE [sp_tts_ack_rev]
GO

CREATE PROCEDURE [sp_tts_ack_rev]
  @p_uuid varchar(100),
  @p_Send VARCHAR(4000),
  @p_Rev  VARCHAR(4000),
  @P_CODE VARCHAR(100) OUT,
  @P_MSG  VARCHAR(4000) OUT
AS
  DECLARE @retcode varchar(200)='';
  DECLARE @v_DATE1 DATETIME = GETDATE(), @v_s INT = 0;
BEGIN
  BEGIN TRY
    SET @retcode = json_value(@p_Rev, '$.code');
    SET @P_CODE = '0';
  END TRY
  BEGIN CATCH END CATCH

  IF ISNULL(@retcode,'') = '0'
  BEGIN
    DELETE FROM wcs_tools_feedback WHERE id=@p_uuid;
    SET @P_MSG = '[tts-ack]ok';
  END
  ELSE
  BEGIN
    UPDATE wcs_tools_feedback SET flag='0', retry_count=ISNULL(retry_count,0)+1
    WHERE id=@p_uuid;
    SET @P_MSG = '[tts-ack]failed,code=' + ISNULL(@retcode,'?') + ',retry later';
  END

  SET @v_s = DATEDIFF(ms, @v_DATE1, GETDATE()) / 100;
  EXEC [dbo].[sp_create_wcs_log]
    'tts_ack', NULL, NULL, NULL, NULL, NULL, @P_CODE, @P_MSG,
    'sp_tts_ack_rev', @v_s, 'tts-ack', @p_Rev, @p_Send, NULL, NULL, NULL, NULL;
END

GO

-- ----------------------------
-- Procedure structure for sp_tts_ack_send
-- ----------------------------
DROP PROCEDURE [sp_tts_ack_send]
GO
CREATE PROCEDURE [sp_tts_ack_send]
  @P_uuid VARCHAR(4000) OUT,
  @p_url VARCHAR(4000) OUT, /* 新增 */
  @p_Send VARCHAR(4000) OUT,
  @P_CODE VARCHAR(100) OUT,
  @P_MSG  VARCHAR(4000) OUT
AS
  DECLARE @header VARCHAR(4000) = '';
  DECLARE @body   VARCHAR(4000) = '';
  DECLARE @id varchar(100),@deviceName varchar(50);
BEGIN
  SET @P_uuid=''; SET @p_Send='';
  SELECT TOP 1 @id=id, @body=msg,@deviceName=deviceName FROM wcs_tools_feedback
  WHERE type='tts_ack' AND flag='0' ORDER BY create_date ASC;
  IF @@ROWCOUNT = 1
  BEGIN
    UPDATE wcs_tools_feedback SET flag='1' WHERE id=@id;
    SET @header = 'Content-Type@@application/json;S-Auth@@{$TTS#;#'
            + dbo.f_tools_mem('tts_secretKey_' + @deviceName) + '#;#accessKey='
            + dbo.f_tools_mem('tts_accessKey_' + @deviceName) + '&paramBody=' + ISNULL(@body,'') + '$}';
    SET @p_url = 'accessKey=' + dbo.f_tools_mem('tts_accessKey_' + @deviceName); 
    SET @p_Send = ISNULL(@header,'') + '#####' + ISNULL(@body,'');
    SET @P_uuid = @id;
    SET @P_MSG  = '[tts-ack]batch ack';
  END
END
GO

-- ----------------------------
-- Procedure structure for sp_tts_blockcfg_rev
-- ----------------------------
DROP PROCEDURE [sp_tts_blockcfg_rev]
GO
CREATE PROCEDURE [sp_tts_blockcfg_rev]
  @p_uuid varchar(100),
  @p_Send VARCHAR(4000),
  @p_Rev  VARCHAR(4000),
  @P_CODE VARCHAR(100) OUT,
  @P_MSG  VARCHAR(4000) OUT
AS
  DECLARE @retcode varchar(200)='';
  DECLARE @dev varchar(50);
  DECLARE @v_DATE1 DATETIME = GETDATE(), @v_s INT = 0;
BEGIN
  BEGIN TRY
    IF CHARINDEX('#####', @p_Rev) > 0
      SET @p_Rev = SUBSTRING(@p_Rev, CHARINDEX('#####', @p_Rev) + 5, LEN(@p_Rev));
      
    SET @retcode = json_value(@p_Rev, '$.code');
    SET @P_CODE = '0';
  END TRY
  BEGIN CATCH END CATCH

  SELECT @dev=deviceName FROM wcs_tools_feedback WHERE id=@p_uuid;

  IF ISNULL(@retcode,'') = '0'
  BEGIN
    /* data 为数组 [{blockCode,blockStatus,collectStatus}] */
    /* 1) 格口状态落框架出口表 wcs_pos_config（不再用 tts_block）：以 wcs_to_pos = blockCode */
    /*    为键更新 stn_st（1=锁格，0=正常）。collectStatus 在 pos_config 无对应列，暂不落（待确认）。 */
    UPDATE p SET p.stn_st = CASE s.bs WHEN 'true' THEN '1' ELSE '0' END,
                 p.update_date = GETDATE()
    FROM wcs_pos_config p
    JOIN (SELECT json_value(value,'$.blockCode') AS bc,
                 json_value(value,'$.blockStatus') AS bs
          FROM OPENJSON(@p_Rev, '$.data')) s ON p.wcs_to_pos = s.bc;
    /* 2) 给本台 PLC 下发 0E：仅本次返回中锁格的格口才发（解锁不走此路，走 2.14/2.16） */
    DECLARE @hex varchar(4000), @bc2 varchar(64);
    DECLARE cur2 CURSOR LOCAL FAST_FORWARD FOR
      SELECT json_value(value,'$.blockCode')
      FROM OPENJSON(@p_Rev, '$.data')
      WHERE json_value(value,'$.blockStatus') = 'true';
    OPEN cur2;
    FETCH NEXT FROM cur2 INTO @bc2;
    WHILE @@FETCH_STATUS = 0
    BEGIN
      EXEC sp_tts_plc_make_0e @bc2, 1, @dev, @hex OUTPUT;
      INSERT INTO wcs_tools_hand_cmd(dvc_no, cmd_name, cmd)
      VALUES (@dev, 'TTS chute lock ' + @bc2, @hex);
      FETCH NEXT FROM cur2 INTO @bc2;
    END
    CLOSE cur2; DEALLOCATE cur2;
    DELETE FROM wcs_tools_feedback WHERE id=@p_uuid;
    
    SET @P_MSG = '[tts-blockcfg]block config applied';
  END
  ELSE
  BEGIN
    UPDATE wcs_tools_feedback SET flag='0', retry_count=ISNULL(retry_count,0)+1
    WHERE id=@p_uuid;
    SET @P_MSG = '[tts-blockcfg]failed,code=' + ISNULL(@retcode,'?') + ',retry later';
  END

  SET @v_s = DATEDIFF(ms, @v_DATE1, GETDATE()) / 100;
  EXEC [dbo].[sp_create_wcs_log]
    'tts_blockcfg', NULL, NULL, NULL, NULL, NULL, @P_CODE, @P_MSG,
    'sp_tts_blockcfg_rev', @v_s, 'tts-blockcfg', @p_Rev, @p_Send, NULL, NULL, NULL, NULL;
END
GO

