-- ----------------------------
-- Procedure structure for sp_tts_blockquery_rev
-- ----------------------------
DROP PROCEDURE [sp_tts_blockquery_rev]
GO

CREATE PROCEDURE [sp_tts_blockquery_rev]
  @sMsg   VARCHAR(4000),
  @s_send VARCHAR(4000) OUT,
  @p_code VARCHAR(100) OUT,
  @p_msg  VARCHAR(4000) OUT
AS
  DECLARE @bc varchar(64) = '';
  DECLARE @p int, @amp int;
  DECLARE @st bit = 0;
  DECLARE @v_DATE1 DATETIME = GETDATE(), @v_s INT = 0;
BEGIN
  SET @p = CHARINDEX('blockCode=', @sMsg);
  IF @p > 0
  BEGIN
    SET @bc = SUBSTRING(@sMsg, @p + 10, 64);
    SET @amp = CHARINDEX('&', @bc);
    IF @amp > 0 SET @bc = LEFT(@bc, @amp - 1);
  END
  SELECT @st = block_status FROM tts_block WHERE block_code = @bc;
  SET @s_send = '{"code":0,"msg":"成功","data":'
             + CASE WHEN @st = 1 THEN 'true' ELSE 'false' END + '}';
  SET @p_code = '0';
  SET @p_msg  = '[tts-blockquery]blockCode=' + @bc;

  SET @v_s = DATEDIFF(ms, @v_DATE1, GETDATE()) / 100;
  EXEC [dbo].[sp_create_wcs_log]
    'tts_blockquery', @bc, NULL, NULL, NULL, NULL, @p_code, @p_msg,
    'sp_tts_blockquery_rev', @v_s, 'tts-srv1', @sMsg, @s_send, NULL, NULL, NULL, NULL;
END

