CREATE PROCEDURE [sp_tts_check_rev]
  @p_uuid varchar(100),
  @p_Send VARCHAR(4000),
  @p_Rev  VARCHAR(4000),
  @P_CODE VARCHAR(100) OUT,
  @P_MSG  VARCHAR(4000) OUT
AS
  DECLARE @retcode varchar(200)='';
  DECLARE @barcode varchar(4000)='';
  DECLARE @v_DATE1 DATETIME = GETDATE(), @v_s INT = 0;
BEGIN
  BEGIN TRY
    SET @retcode = json_value(@p_Rev, '$.code');
    SET @P_CODE = '0';
  END TRY
  BEGIN CATCH END CATCH

  SELECT @barcode = barcode FROM wcs_tools_feedback WHERE id=@p_uuid;

  IF ISNULL(@retcode,'') = '0'
  BEGIN
    DELETE FROM wcs_tools_feedback WHERE id=@p_uuid;
    SET @P_MSG = '[tts-check]ok,barcode=' + ISNULL(@barcode,'');
  END
  ELSE
  BEGIN
    DECLARE @rc int;
    SELECT @rc = ISNULL(retry_count,0)+1 FROM wcs_tools_feedback WHERE id=@p_uuid;
    IF @rc >= 3
      DELETE FROM wcs_tools_feedback WHERE id=@p_uuid;
    ELSE
      UPDATE wcs_tools_feedback SET flag='0', retry_count=@rc WHERE id=@p_uuid;
    SET @P_MSG = '[tts-check]failed,code=' + ISNULL(@retcode,'?') + ',retry later';
  END

  SET @v_s = DATEDIFF(ms, @v_DATE1, GETDATE()) / 100;
  EXEC [dbo].[sp_create_wcs_log]
    'tts_check', @barcode, NULL, NULL, NULL, NULL, @P_CODE, @P_MSG,
    'sp_tts_check_rev', @v_s, 'tts-check', @p_Rev, @p_Send, NULL, NULL, NULL, NULL;
END
GO

