GO
CREATE PROCEDURE [sp_tts_check_send]
  @P_uuid VARCHAR(4000) OUT,
  @p_url VARCHAR(4000) OUT, /* 新增 */
  @p_Send VARCHAR(4000) OUT,
  @P_CODE VARCHAR(100) OUT,
  @P_MSG  VARCHAR(4000) OUT
AS
  DECLARE @header VARCHAR(4000) = '';
  DECLARE @body   VARCHAR(4000) = '';
  DECLARE @id varchar(100), @barcode varchar(4000), @deviceName varchar(50);
  DECLARE @result varchar(64);
BEGIN
  SET @P_uuid=''; SET @p_Send='';
  /* 取待发行，连同 result 拆列一起查出（不再读 msg） */
  SELECT TOP 1 @id=id, @barcode=barcode, @deviceName=deviceName, @result=result
  FROM wcs_tools_feedback
  WHERE type='tts_check' AND flag='0' ORDER BY create_date ASC;
  IF @@ROWCOUNT = 1
  BEGIN
    UPDATE wcs_tools_feedback SET flag='1' WHERE id=@id;
    /* body 由拆列现组装：canonical JSON；result 1=已落格 2=未落格 */
    SET @body = '{"name":"' + dbo.f_tools_mem('tts_deviceName_' + @deviceName)
              + '","barcode":"' + ISNULL(@barcode,'')
              + '","result":' + ISNULL(@result,'2')
              + ',"timestamp":' + CAST(DATEDIFF_BIG(MILLISECOND,'1970-01-01',SYSUTCDATETIME()) AS varchar(20)) + '}';
    SET @header = 'Content-Type@@application/json;S-Auth@@{$TTS#;#'
                + dbo.f_tools_mem('tts_secretKey_' + @deviceName) + '#;#accessKey='
                + dbo.f_tools_mem('tts_accessKey_' + @deviceName) + '&paramBody=' + ISNULL(@body,'') + '$}';
    SET @p_url = 'accessKey=' + dbo.f_tools_mem('tts_accessKey_' + @deviceName); 
    SET @p_Send = ISNULL(@header,'') + '#####' + ISNULL(@body,'');
    SET @P_uuid = @id;
    SET @P_MSG  = '[tts-check]barcode=' + ISNULL(@barcode,'');
  END
END
