-- ----------------------------
-- Procedure structure for sp_tts_devstatus_rev
-- ----------------------------
DROP PROCEDURE [sp_tts_devstatus_rev]
GO
/* sp_tts_devstatus_rev V2 (2026-10-26) */
/* 改动：与 send V2 配套——@p_uuid 为本批 feedback 行 id 清单， */
/*   成功按清单删行；失败按清单回滚 flag='0' 并 retry_count+1，满 3 次删行丢弃 */
/* @p_uuid 参数放宽为 VARCHAR(4000)（原 100 装不下 40 个 id 的清单） */
/* 不再从 @p_Send 反查 name（批次身份已由 @p_uuid 携带） */
CREATE PROCEDURE [sp_tts_devstatus_rev]
  @p_uuid varchar(4000),
  @p_Send VARCHAR(4000),
  @p_Rev  VARCHAR(4000),
  @P_CODE VARCHAR(100) OUT,
  @P_MSG  VARCHAR(4000) OUT
AS
  DECLARE @retcode varchar(200)='';
  DECLARE @v_DATE1 DATETIME = GETDATE(), @v_s INT = 0;
BEGIN
  BEGIN TRY
    SET @retcode = json_value(@p_Rev, '$.code');
    SET @P_CODE = '0';
  END TRY
  BEGIN CATCH END CATCH

  IF ISNULL(@retcode,'') = '0'
  BEGIN
    DELETE FROM wcs_tools_feedback
    WHERE type='tts_devstatus'
      AND id IN (SELECT TRY_CAST(value AS int) FROM STRING_SPLIT(@p_uuid, ','));
    SET @P_MSG = '[tts-devstatus]report ok';
  END
  ELSE
  BEGIN
    UPDATE wcs_tools_feedback
    SET flag='0', retry_count=ISNULL(retry_count,0)+1
    WHERE type='tts_devstatus'
      AND id IN (SELECT TRY_CAST(value AS int) FROM STRING_SPLIT(@p_uuid, ','));
    /* 同批连败 3 次：删行丢弃，避免毒行堵队 */
    DELETE FROM wcs_tools_feedback
    WHERE type='tts_devstatus' AND ISNULL(retry_count,0)>=3
      AND id IN (SELECT TRY_CAST(value AS int) FROM STRING_SPLIT(@p_uuid, ','));
    SET @P_MSG = '[tts-devstatus]failed,code=' + ISNULL(@retcode,'?') + ',retry later';
  END

  SET @v_s = DATEDIFF(ms, @v_DATE1, GETDATE()) / 100;
  EXEC [dbo].[sp_create_wcs_log]
    'tts_devstatus', @p_uuid, NULL, NULL, NULL, NULL, @P_CODE, @P_MSG,
    'sp_tts_devstatus_rev', @v_s, 'tts-devstatus', @p_Rev, @p_Send, NULL, NULL, NULL, NULL;
END
GO

-- ----------------------------
-- Procedure structure for sp_tts_devstatus_send
-- ----------------------------
DROP PROCEDURE [sp_tts_devstatus_send]
GO
/* sp_tts_devstatus_send V2 (2026-10-26) */
/* 改动：数据源由 wcs_tools_stn 改为 wcs_tools_feedback 队列（type='tts_devstatus'， */
/*   一行=一个格口的一次状态：deviceName=设备后缀、deviceBlock=格口号、status、errorCode） */
/*   仍按单设备整批（最早待发行所属设备、最多 40 条、create_date 序） */
/* @P_uuid 改为本批行 id 清单（逗号分隔），rev 按清单精准关行（不再用随机 GUID） */
/* 顺手修：@p_url 正式赋值（原仅有一行被注释且引用了不存在的 @deviceName）； */
/*   @p_url 开头初始化 ''（防动态 URL 模式下 enCodeMsg 对 NULL 抛 NPE） */
CREATE PROCEDURE [sp_tts_devstatus_send]
  @P_uuid VARCHAR(4000) OUT,
  @p_url VARCHAR(4000) OUT,
  @p_Send VARCHAR(4000) OUT,
  @P_CODE VARCHAR(100) OUT,
  @P_MSG  VARCHAR(4000) OUT
AS
  DECLARE @header VARCHAR(4000) = '';
  DECLARE @body   VARCHAR(4000) = '';
  DECLARE @items  VARCHAR(4000) = '';
  DECLARE @ids    VARCHAR(4000) = '';
  DECLARE @id varchar(100), @dev varchar(50);
  DECLARE @c varchar(200), @st varchar(100), @ec varchar(100);
BEGIN
  SET @P_uuid=''; SET @p_url=''; SET @p_Send='';

  /* 取最早一条待发行所属设备，本批只发这一台 */
  SELECT TOP 1 @dev=deviceName FROM wcs_tools_feedback
  WHERE type='tts_devstatus' AND flag='0' ORDER BY create_date ASC;
  IF ISNULL(@dev,'')='' RETURN;

  DECLARE cur CURSOR LOCAL FAST_FORWARD FOR
    SELECT TOP 40 id, deviceBlock, status, errorCode FROM wcs_tools_feedback
    WHERE type='tts_devstatus' AND flag='0' AND deviceName=@dev
    ORDER BY create_date ASC;
  OPEN cur;
  FETCH NEXT FROM cur INTO @id, @c, @st, @ec;
  WHILE @@FETCH_STATUS = 0
  BEGIN
    SET @items = @items + ',{"code":"' + ISNULL(@c,'') + '","status":"' + ISNULL(@st,'')
               + '","errorCode":"' + ISNULL(@ec,'') + '"}';
    SET @ids = @ids + ',' + @id;
    /* 拼入即置 1（已领），成败由 rev 按 @P_uuid 清单关行/回滚 */
    UPDATE wcs_tools_feedback SET flag='1' WHERE id=@id;
    FETCH NEXT FROM cur INTO @id, @c, @st, @ec;
  END
  CLOSE cur; DEALLOCATE cur;

  IF @items <> ''
  BEGIN
    /* canonical JSON：键顺序固定、无空格（签名要求字节一致） */
    SET @body = '{"name":"' + dbo.f_tools_mem('tts_deviceName_' + @dev) + '","deviceBlocks":['
            + SUBSTRING(@items, 2, 4000) + ']}';
    SET @header = 'Content-Type@@application/json;S-Auth@@{$TTS#;#'
              + dbo.f_tools_mem('tts_secretKey_' + @dev) + '#;#accessKey='
              + dbo.f_tools_mem('tts_accessKey_' + @dev) + '&paramBody=' + ISNULL(@body,'') + '$}';
    SET @p_url = 'accessKey=' + dbo.f_tools_mem('tts_accessKey_' + @dev);
    SET @p_Send = ISNULL(@header,'') + '#####' + ISNULL(@body,'');
    SET @P_uuid = SUBSTRING(@ids, 2, 4000);
    SET @P_MSG  = '[tts-devstatus]batch sent,dev=' + ISNULL(@dev,'');
  END
END
GO

