-- ----------------------------
-- Procedure structure for sp_tts_event_send
-- ----------------------------
DROP PROCEDURE [sp_tts_event_send]
GO
CREATE PROCEDURE [sp_tts_event_send]
  @P_uuid VARCHAR(4000) OUT,
  @p_url VARCHAR(4000) OUT, /* 新增 */
  @p_Send VARCHAR(4000) OUT,
  @P_CODE VARCHAR(100) OUT,
  @P_MSG  VARCHAR(4000) OUT
AS
  DECLARE @header VARCHAR(4000) = '';
  DECLARE @body   VARCHAR(4000) = '';
  DECLARE @id varchar(100), @barcode varchar(4000), @deviceName varchar(50);
  DECLARE @st varchar(10), @reason varchar(64), @result varchar(64);
BEGIN
  SET @P_uuid=''; SET @p_Send='';
  /* 取待发行，连同 2.8 拆列一起查出（不再读 msg） */
  SELECT TOP 1 @id=id, @barcode=barcode, @deviceName=deviceName,
               @st=sortStatus, @reason=errorReason, @result=result
  FROM wcs_tools_feedback
  WHERE type='tts_event' AND flag='0' ORDER BY create_date ASC;
  IF @@ROWCOUNT = 1
  BEGIN
    UPDATE wcs_tools_feedback SET flag='1' WHERE id=@id;
    /* body 由拆列现组装：canonical JSON（键序固定、无空格，签名要求字节一致）；
       reqTime/respTime 取发送时刻，ext 为固定模板（errorCode/layer 暂空） */
    DECLARE @ts varchar(20) = CAST(DATEDIFF_BIG(MILLISECOND,'1970-01-01',SYSUTCDATETIME()) AS varchar(20));
    SET @body = '{"name":"' + dbo.f_tools_mem('tts_deviceName_' + @deviceName)
              + '","barcode":"' + ISNULL(@barcode,'')
              + '","reqTime":' + @ts + ',"respTime":' + @ts
              + ',"status":' + ISNULL(@st,'1')
              + ',"errorReason":"' + ISNULL(@reason,'')
              + '","result":"' + ISNULL(@result,'')
              + '","ext":"{\"errorCode\":\"\",\"layer\":\"\"}"}';
    SET @header = 'Content-Type@@application/json;S-Auth@@{$TTS#;#'
                + dbo.f_tools_mem('tts_secretKey_' + @deviceName) + '#;#accessKey='
                + dbo.f_tools_mem('tts_accessKey_' + @deviceName) + '&paramBody=' + ISNULL(@body,'') + '$}';
    SET @p_url = 'accessKey=' + dbo.f_tools_mem('tts_accessKey_' + @deviceName); 
    SET @p_Send = ISNULL(@header,'') + '#####' + ISNULL(@body,'');
    SET @P_uuid = @id;
    SET @P_MSG  = '[tts-event]barcode=' + ISNULL(@barcode,'');
  END
END
GO

-- ----------------------------
-- Procedure structure for sp_tts_getsort_rev
-- ----------------------------
DROP PROCEDURE [sp_tts_getsort_rev]
GO
/* sp_tts_getsort_rev V2 (2026-10-26) */
/* 唯一改动：开头加 ##### 前缀截取（网关回包带 httpCode=200;httpMsg=OK##### 前缀， */
/* 不截则 json_value/OPENJSON 整体解析失败、retcode 恒空、全部分支误走 failed） */
/* 其余逻辑与用户现行版一致（成功分支 grids 消费方问题待确认，未动） */
CREATE PROCEDURE [sp_tts_getsort_rev]
  @p_uuid varchar(100),
  @p_Send VARCHAR(4000),
  @p_Rev  VARCHAR(4000),
  @P_CODE VARCHAR(100) OUT,
  @P_MSG  VARCHAR(4000) OUT
AS
  DECLARE @retcode varchar(200)='';
  DECLARE @first varchar(64), @grids varchar(2000);
  DECLARE @v_DATE1 DATETIME = GETDATE(), @v_s INT = 0;
BEGIN
  IF CHARINDEX('#####', @p_Rev) > 0
    SET @p_Rev = SUBSTRING(@p_Rev, CHARINDEX('#####', @p_Rev) + 5, LEN(@p_Rev));

  BEGIN TRY
    SET @retcode = json_value(@p_Rev, '$.code');
    SET @P_CODE = '0';
  END TRY
  BEGIN CATCH END CATCH

  IF ISNULL(@retcode,'') = '0'
  BEGIN
    SELECT TOP 1 @first = value FROM OPENJSON(@p_Rev, '$.data');
    /* 99999（文档）/ 999（会上口头）：云端还没分配格口，回队继续轮询 */
    IF @first IN ('99999','999') OR @first IS NULL
    BEGIN
      DECLARE @rc int;
      SELECT @rc = ISNULL(retry_count,0)+1 FROM wcs_tools_feedback WHERE id=@p_uuid;
      /* 轮询次数借 retry_count 记，上限 tts_max_poll_cycles（缺省 5），到顶删行 */
      IF @rc >= ISNULL(TRY_CAST(dbo.f_tools_mem('tts_max_poll_cycles') AS int), 5)
      begin
        DELETE FROM wcs_tools_feedback WHERE id=@p_uuid;
        SET @P_MSG = @P_MSG
      end
      ELSE
        UPDATE wcs_tools_feedback SET flag='0', retry_count=@rc WHERE id=@p_uuid;
      SET @P_MSG = '[tts-getsort]waiting(999xx),poll=' + CAST(ISNULL(@rc,0) AS varchar(10));
    END
    ELSE
    BEGIN
      SELECT @grids = STRING_AGG(value, ',') FROM OPENJSON(@p_Rev, '$.data');
      DELETE FROM wcs_tools_feedback WHERE id=@p_uuid;
      SET @P_MSG = '[tts-getsort]ok,grids=' + ISNULL(@grids,'');
    END
  END
  ELSE
  BEGIN
    DECLARE @rc2 int;
    SELECT @rc2 = ISNULL(retry_count,0)+1 FROM wcs_tools_feedback WHERE id=@p_uuid;
    IF @rc2 >= 3
    begin
     DELETE FROM wcs_tools_feedback WHERE id=@p_uuid;
     SET @P_MSG = @P_MSG
    end
    ELSE
      UPDATE wcs_tools_feedback SET flag='0', retry_count=@rc2 WHERE id=@p_uuid;
    SET @P_MSG = '[tts-getsort]failed,code=' + ISNULL(@retcode,'?') + ',retry later';
  END

  SET @v_s = DATEDIFF(ms, @v_DATE1, GETDATE()) / 100;
  EXEC [dbo].[sp_create_wcs_log]
    'tts_getsort', @p_uuid, NULL, NULL, NULL, NULL, @P_CODE, @P_MSG,
    'sp_tts_getsort_rev', @v_s, 'tts-getsort', @p_Rev, @p_Send, NULL, NULL, NULL, NULL;
END
GO

