-- Procedure structure for sp_tts_getsort_send
-- ----------------------------
DROP PROCEDURE [sp_tts_getsort_send]
GO
CREATE PROCEDURE [sp_tts_getsort_send]
  @P_uuid VARCHAR(4000) OUT,
  @p_url  VARCHAR(4000) OUT,
  @p_Send VARCHAR(4000) OUT,
  @P_CODE VARCHAR(100) OUT,
  @P_MSG  VARCHAR(4000) OUT
AS
  DECLARE @header VARCHAR(4000) = '';
  DECLARE @param  VARCHAR(4000) = '';
  DECLARE @id varchar(100), @barcode varchar(4000), @dev varchar(50);
  DECLARE @deviceBlock varchar(64);
  DECLARE @length int, @width int, @height int, @weight int;
BEGIN
  SET @P_uuid=''; SET @p_url=''; SET @p_Send='';
  /* 取待发行（队列驱动，与量方同构：拆列现组装 param，不读 msg） */
  SELECT TOP 1 @id=id, @barcode=barcode, @dev=deviceName,
               @deviceBlock=deviceBlock, @length=length, @width=width,
               @height=height, @weight=weight
  FROM wcs_tools_feedback
  WHERE type='tts_getsort' AND flag='0' ORDER BY create_date ASC;
  IF @@ROWCOUNT = 1
  BEGIN
    UPDATE wcs_tools_feedback SET flag='1' WHERE id=@id;
    SET @param = 'name=' + dbo.f_tools_mem('tts_deviceName_' + @dev)
      + '&deviceBlock=' + ISNULL(@deviceBlock,'')
      + '&barcode=' + ISNULL(@barcode,'')
      + '&requestID=' + LOWER(REPLACE(CAST(NEWID() AS VARCHAR(36)), '-', ''))
      + '&weight=' + CAST(ISNULL(@weight,0) AS varchar(20))
      + '&length=' + CAST(ISNULL(@length,0) AS varchar(20))
      + '&width=' + CAST(ISNULL(@width,0) AS varchar(20))
      + '&height=' + CAST(ISNULL(@height,0) AS varchar(20))
      + '&timestamp=' + CAST(DATEDIFF_BIG(MILLISECOND,'1970-01-01',SYSUTCDATETIME()) AS varchar(20))
      + '&accessKey=' + dbo.f_tools_mem('tts_accessKey_' + @dev);
    SET @header = 'S-Auth@@{$TTS#;#' + dbo.f_tools_mem('tts_secretKey_' + @dev)
                + '#;#' + @param + '$}';
    SET @P_uuid = @id;
    SET @p_url  = 'api/sorter/getSort?' + @param;
    SET @p_Send = ISNULL(@header,'') + '#####';
    SET @P_MSG  = '[tts-getsort]barcode=' + ISNULL(@barcode,'');
  END
END
GO

