CREATE PROCEDURE [sp_tts_heartbeat_sd1_rev]
  @p_uuid varchar(100),
  @p_Send VARCHAR(4000),
  @p_Rev  VARCHAR(4000),
  @P_CODE VARCHAR(100) OUT,
  @P_MSG  VARCHAR(4000) OUT
AS
  DECLARE @retcode varchar(200)='';
  DECLARE @v_DATE1 DATETIME = GETDATE(), @v_s INT = 0;
BEGIN
  BEGIN TRY
    IF CHARINDEX('#####', @p_Rev) > 0
      SET @p_Rev = SUBSTRING(@p_Rev, CHARINDEX('#####', @p_Rev) + 5, LEN(@p_Rev));
      
    SET @retcode = json_value(@p_Rev, '$.code');
    SET @P_CODE = '0';
  END TRY
  BEGIN CATCH END CATCH

  IF ISNULL(@retcode,'') = '1003'  /* 上位判定设备离线：关会话，入队 login 指令重登 */
  BEGIN
    UPDATE wcs_mem_config SET mem_item_value='0', update_date=GETDATE()
    WHERE mem_item_no='tts_session_online_TTS-SD1';
    INSERT INTO wcs_tools_feedback(type, flag, devicename) VALUES ('tts_login','0','TTS-SD1');
  END
  SET @P_MSG = '[tts-heartbeat]code=' + ISNULL(@retcode,'?');

  SET @v_s = DATEDIFF(ms, @v_DATE1, GETDATE()) / 100;
  EXEC [dbo].[sp_create_wcs_log]
    'tts_heartbeat', NULL, NULL, NULL, NULL, NULL, @P_CODE, @P_MSG,
    'sp_tts_heartbeat_rev', @v_s, 'tts-heartbeat', @p_Rev, @p_Send, NULL, NULL, NULL, NULL;
END
