-- ----------------------------
-- Procedure structure for sp_tts_login_rev
-- ----------------------------
DROP PROCEDURE [sp_tts_login_rev]
GO
CREATE PROCEDURE [sp_tts_login_rev]
  @p_uuid varchar(100),
  @p_Send VARCHAR(4000),
  @p_Rev  VARCHAR(4000),
  @P_CODE VARCHAR(100) OUT,
  @P_MSG  VARCHAR(4000) OUT
AS
  DECLARE @retcode varchar(200)='', @message varchar(1000)='',@deviceName varchar(50)
  DECLARE @v_DATE1 DATETIME = GETDATE(), @v_s INT = 0;
BEGIN
  BEGIN TRY
    IF CHARINDEX('#####', @p_Rev) > 0
      SET @p_Rev = SUBSTRING(@p_Rev, CHARINDEX('#####', @p_Rev) + 5, LEN(@p_Rev));
    
		SELECT @retcode=code, @message=msg
    FROM (SELECT a.parent_ID, a.NAME, a.StringValue
          FROM f_tools_parseJSON(@p_Rev) a
          WHERE ISNULL(a.name,'') IN ('msg','code')) t1
    PIVOT (MAX(StringValue) FOR NAME IN (code, msg)) AS t2;
    SET @P_CODE = '0';
  END TRY
  BEGIN CATCH END CATCH

  IF ISNULL(@retcode,'') = '0'
  BEGIN
    select @deviceName=deviceName FROM wcs_tools_feedback WHERE id=@p_uuid;
    /*DELETE FROM wcs_tools_feedback WHERE id=@p_uuid; */
    /* 会话建立：开启心跳保活 */
    UPDATE wcs_mem_config SET mem_item_oldvalue=mem_item_value, mem_item_value='1',
           update_date=GETDATE() WHERE mem_item_no='tts_session_online_'+@deviceName;
    /* 登录成功：入队 2.4 格口配置查询指令（tts-blockcfg 行拾取后 GET） */
    INSERT INTO wcs_tools_feedback(type, flag, deviceName) VALUES ('tts_blockcfg','0',@deviceName);
    /* 登录成功：2.5 先全量上报一次格口状态 */
    /* 全量上报：登录成功把设备状态表全部标为待上传，后续由 devstatus 逐批（每批 40）发出 */
    UPDATE wcs_tools_stn SET flag=0;
    SET @P_MSG = '[tts-login]login success';
  END
  ELSE
  BEGIN
    /* 失败（含 1003）：指令回滚待重试，下个轮询周期再发 */
    UPDATE wcs_tools_feedback SET flag='0', retry_count=ISNULL(retry_count,0)+1
    WHERE id=@p_uuid;
    SET @P_MSG = '[tts-login]login failed,retcode:' + ISNULL(@retcode,'?')
               + ',message:' + ISNULL(@message,'') + ',retry later';
  END

  SET @v_s = DATEDIFF(ms, @v_DATE1, GETDATE()) / 100;
  EXEC [dbo].[sp_create_wcs_log]
    'tts_login', NULL, NULL, NULL, NULL, NULL, @P_CODE, @P_MSG,
    'sp_tts_login_rev', @v_s, 'tts-login', @p_Rev, @p_Send, NULL, NULL, NULL, NULL;
END
GO

