CREATE PROCEDURE [sp_tts_login_send]
  @P_uuid VARCHAR(4000) OUT,
  @p_url  VARCHAR(4000) OUT,
  @p_Send VARCHAR(4000) OUT,
  @P_CODE VARCHAR(100) OUT,
  @P_MSG  VARCHAR(4000) OUT
AS
  DECLARE @header VARCHAR(4000) = '';
  DECLARE @param  VARCHAR(4000) = '',@deviceName varchar(50)
  DECLARE @id varchar(100);
BEGIN
  SET @P_uuid=''; SET @p_url=''; SET @p_Send='';
  /* 队列驱动：取最早一条待处理 tts_login 指令（register_online / 1003 重登时入队） */
  SELECT TOP 1 @id=id,@deviceName=deviceName FROM wcs_tools_feedback
  WHERE type='tts_login' AND flag='0' ORDER BY create_date ASC;
  IF @@ROWCOUNT = 1
  BEGIN
    UPDATE wcs_tools_feedback SET flag='1' WHERE id=@id; 
    SET @param = 'name=' + dbo.f_tools_mem('tts_deviceName_'+@deviceName)
               + '&accessKey=' + dbo.f_tools_mem('tts_accessKey_'+@deviceName);
    SET @header = 'S-Auth@@{$TTS#;#' + dbo.f_tools_mem('tts_secretKey_'+@deviceName)
                + '#;#' + @param + '$}';
    SET @P_uuid = @id;
    SET @p_url  = 'api/sorter/login?' + @param;
    SET @p_Send = ISNULL(@header,'') + '#####';  /* GET：只有 header */
    SET @P_MSG  = '[tts-login]login request';
  END
END
GO

-- ----------------------------
-- Procedure structure for sp_tts_logout_rev
-- ----------------------------
DROP PROCEDURE [sp_tts_logout_rev]
GO
CREATE PROCEDURE [sp_tts_logout_rev]
  @p_uuid varchar(100),
  @p_Send VARCHAR(4000),
  @p_Rev  VARCHAR(4000),
  @P_CODE VARCHAR(100) OUT,
  @P_MSG  VARCHAR(4000) OUT
AS
  DECLARE @retcode varchar(200)='', @message varchar(1000)='',@deviceName varchar(50);
  DECLARE @v_DATE1 DATETIME = GETDATE(), @v_s INT = 0;
BEGIN
  BEGIN TRY
    IF CHARINDEX('#####', @p_Rev) > 0
      SET @p_Rev = SUBSTRING(@p_Rev, CHARINDEX('#####', @p_Rev) + 5, LEN(@p_Rev));
  
    SELECT @retcode=code, @message=msg
    FROM (SELECT a.parent_ID, a.NAME, a.StringValue
          FROM f_tools_parseJSON(@p_Rev) a
          WHERE ISNULL(a.name,'') IN ('msg','code')) t1
    PIVOT (MAX(StringValue) FOR NAME IN (code, msg)) AS t2;
    SET @P_CODE = '0';
  END TRY
  BEGIN CATCH END CATCH

  IF ISNULL(@retcode,'') = '0'
  BEGIN
    select @deviceName=deviceName FROM wcs_tools_feedback WHERE id=@p_uuid;
    DELETE FROM wcs_tools_feedback WHERE id=@p_uuid;
    UPDATE wcs_mem_config SET mem_item_oldvalue=mem_item_value, mem_item_value='0',
           update_date=GETDATE() WHERE mem_item_no='tts_session_online_'+@deviceName;
    SET @P_MSG = '[tts-logout]logout success';
  END
  ELSE
  BEGIN
    /* 失败：指令回滚待重试（若上位回"未登录"类码，目的已达，联调时在此改为删行收工） */
    UPDATE wcs_tools_feedback SET flag='0', retry_count=ISNULL(retry_count,0)+1
    WHERE id=@p_uuid;
    SET @P_MSG = '[tts-logout]logout failed,retcode:' + ISNULL(@retcode,'?')
               + ',message:' + ISNULL(@message,'') + ',retry later';
  END

  SET @v_s = DATEDIFF(ms, @v_DATE1, GETDATE()) / 100;
  EXEC [dbo].[sp_create_wcs_log]
    'tts_logout', NULL, NULL, NULL, NULL, NULL, @P_CODE, @P_MSG,
    'sp_tts_logout_rev', @v_s, 'tts-logout', @p_Rev, @p_Send, NULL, NULL, NULL, NULL;
END
GO

