-- ----------------------------
-- Procedure structure for sp_tts_measure_rev
-- ----------------------------
DROP PROCEDURE [sp_tts_measure_rev]
GO
CREATE PROCEDURE [sp_tts_measure_rev]
  @p_uuid varchar(100),
  @p_Send VARCHAR(4000),
  @p_Rev  VARCHAR(4000),
  @P_CODE VARCHAR(100) OUT,
  @P_MSG  VARCHAR(4000) OUT
AS
  DECLARE @retcode varchar(200)='';
  DECLARE @barcode varchar(4000)='', @grids varchar(2000), @sf varchar(10), @eff varchar(4000);
  DECLARE @v_DATE1 DATETIME = GETDATE(), @v_s INT = 0;
BEGIN
  BEGIN TRY
    SET @retcode = json_value(@p_Rev, '$.code');
    SET @P_CODE = '0';
  END TRY
  BEGIN CATCH END CATCH

  IF ISNULL(@retcode,'') = '0'
  BEGIN
    SELECT @grids = STRING_AGG(value, ',') FROM OPENJSON(@p_Rev, '$.data.grids');
    SET @sf  = json_value(@p_Rev, '$.data.sortFlag');  /* 'true'/'false' */
    SET @barcode = json_value(@p_Rev, '$.data.barcode');
    DELETE FROM wcs_tools_feedback WHERE id=@p_uuid;
    SET @P_MSG = '[tts-measure]ok,barcode=' + ISNULL(@barcode,'') + ',sortFlag=' + ISNULL(@sf,'?')
		  +',grids='+ISNULL(@grids,'')
  END
  ELSE
  BEGIN
    DECLARE @rc int;
    SELECT @rc = ISNULL(retry_count,0)+1 FROM wcs_tools_feedback WHERE id=@p_uuid;
    IF @rc >= 3    
      DELETE FROM wcs_tools_feedback WHERE id=@p_uuid;    
    ELSE 
		  UPDATE wcs_tools_feedback SET flag='0', retry_count=@rc WHERE id=@p_uuid;
    SET @P_MSG = '[tts-measure]failed,code=' + ISNULL(@retcode,'?') + ',retry later';
  END

  SET @v_s = DATEDIFF(ms, @v_DATE1, GETDATE()) / 100;
  EXEC [dbo].[sp_create_wcs_log]
    'tts_measure', @barcode, NULL, NULL, NULL, NULL, @P_CODE, @P_MSG,
    'sp_tts_measure_rev', @v_s, 'tts-measure', @p_Rev, @p_Send, NULL, NULL, NULL, NULL;
END
GO

-- ----------------------------
-- Procedure structure for sp_tts_measure_send
-- ----------------------------
DROP PROCEDURE [sp_tts_measure_send]
GO
CREATE PROCEDURE [sp_tts_measure_send]
  @P_uuid VARCHAR(4000) OUT,
  @p_url VARCHAR(4000) OUT, /* 新增 */
  @p_Send VARCHAR(4000) OUT,
  @P_CODE VARCHAR(100) OUT,
  @P_MSG  VARCHAR(4000) OUT
AS
  DECLARE @header VARCHAR(4000) = '';
  DECLARE @body   VARCHAR(4000) = '';
  DECLARE @id varchar(100), @barcode varchar(4000), @deviceName varchar(50);
  DECLARE @deviceBlock varchar(64);
  DECLARE @length int, @width int, @height int, @weight int;
BEGIN
  SET @P_uuid=''; SET @p_Send='';SET @p_url=''
  /* 取待发行，连同量方拆列一起查出（不再读 msg） */
  SELECT TOP 1 @id=id, @barcode=barcode, @deviceName=deviceName,
               @deviceBlock=deviceBlock, @length=length, @width=width,
               @height=height, @weight=weight
  FROM wcs_tools_feedback
  WHERE type='tts_measure' AND flag='0' ORDER BY create_date ASC;
  IF @@ROWCOUNT = 1
  BEGIN
    UPDATE wcs_tools_feedback SET flag='1' WHERE id=@id;
    /* body 由拆列现组装：canonical JSON（键序固定、无空格，签名要求字节一致） */
    SET @body = '{"name":"' + dbo.f_tools_mem('tts_deviceName_' + @deviceName)
              + '","deviceBlock":"' + ISNULL(@deviceBlock,'')
              + '","barcode":"' + ISNULL(@barcode,'')
              + '","length":' + CAST(ISNULL(@length,0) AS varchar(20))
              + ',"width":' + CAST(ISNULL(@width,0) AS varchar(20))
              + ',"height":' + CAST(ISNULL(@height,0) AS varchar(20))
              + ',"weight":' + CAST(ISNULL(@weight,0) AS varchar(20))
              + ',"timestamp":' + CAST(DATEDIFF_BIG(MILLISECOND,'1970-01-01',SYSUTCDATETIME()) AS varchar(20)) + '}';
    SET @header = 'Content-Type@@application/json;S-Auth@@{$TTS#;#'
                + dbo.f_tools_mem('tts_secretKey_' + @deviceName) + '#;#accessKey='
                + dbo.f_tools_mem('tts_accessKey_' + @deviceName) + '&paramBody=' + ISNULL(@body,'') + '$}';
    SET @p_url = 'accessKey=' + dbo.f_tools_mem('tts_accessKey_' + @deviceName);
    SET @p_Send = ISNULL(@header,'') + '#####' + ISNULL(@body,'');
    SET @P_uuid = @id;
    SET @P_MSG  = '[tts-measure]barcode=' + ISNULL(@barcode,'');
  END
END
GO

-- ----------------------------
-- Procedure structure for sp_tts_pic_send
-- ----------------------------
DROP PROCEDURE [sp_tts_pic_send]
GO

CREATE PROCEDURE [sp_tts_pic_send]
  @P_uuid VARCHAR(4000) OUT,
  @p_Send VARCHAR(MAX) OUT,
  @P_CODE VARCHAR(100) OUT,
  @P_MSG  VARCHAR(4000) OUT
AS
  DECLARE @header VARCHAR(4000) = '';
  DECLARE @body   VARCHAR(MAX) = '';
  DECLARE @id varchar(100), @barcode varchar(4000), @imgpath varchar(1000);
  DECLARE @b64 VARCHAR(MAX);
BEGIN
  SET @P_uuid=''; SET @p_Send='';
  SELECT TOP 1 @id=id, @barcode=barcode, @imgpath=url FROM wcs_tools_feedback
  WHERE type='tts_pic' AND flag='0' ORDER BY create_date ASC;
  IF @@ROWCOUNT = 1
  BEGIN
    UPDATE wcs_tools_feedback SET flag='1' WHERE id=@id;
    BEGIN TRY
      DECLARE @sql nvarchar(2000) = N'SELECT @b64 = CAST('''' AS XML).value(''xs:base64Binary(xs:hexBinary(sql:column("b''))),''VARCHAR(MAX)'') '
        + N'FROM (SELECT * FROM OPENROWSET(BULK ''' + REPLACE(@imgpath,'''','''''') + ''', SINGLE_BLOB) AS t(b)) AS x';
      EXEC sp_executesql @sql, N'@b64 VARCHAR(MAX) OUTPUT', @b64 OUTPUT;
    END TRY
    BEGIN CATCH
      SET @b64 = NULL;
    END CATCH
    IF @b64 IS NULL
    BEGIN
      -- 文件不可读：放回队列稍后重试
      UPDATE wcs_tools_feedback SET flag='0', retry_count=ISNULL(retry_count,0)+1
      WHERE id=@id;
      SET @P_MSG = '[tts-pic]image not readable,retry later,path=' + ISNULL(@imgpath,'');
      RETURN;
    END
    SET @body = '{"name":"' + dbo.f_tools_mem('tts_deviceName')
      + '","deviceBlock":"","barcode":"' + ISNULL(@barcode,'')
      + '","picData":"' + @b64
      + '","timestamp":' + CAST(DATEDIFF_BIG(MILLISECOND,'1970-01-01',SYSUTCDATETIME()) AS varchar(20)) + '}';
    SET @header = 'Content-Type@@application/json;S-Auth@@{$TTS;'
                + dbo.f_tools_mem('tts_secretKey') + ';accessKey='
                + dbo.f_tools_mem('tts_accessKey') + '&paramBody=' + ISNULL(@body,'') + '$}';
    SET @p_Send = ISNULL(@header,'') + '#####' + ISNULL(@body,'');
    SET @P_uuid = @id;
    SET @P_MSG  = '[tts-pic]barcode=' + ISNULL(@barcode,'');
  END
END

GO

-- ----------------------------
-- Procedure structure for sp_tts_plc_make_08
-- ----------------------------
DROP PROCEDURE [sp_tts_plc_make_08]
GO

CREATE PROCEDURE [sp_tts_plc_make_08]
  @ParcelID_hex varchar(8),     -- 原样回传（8 hex 字符）
  @BCR_hex varchar(4),           -- 原样回传（4 hex 字符）
  @barcode_hex varchar(4000),   -- 原样回传（0x05 分隔保留）
  @chute_csv varchar(500),      -- TTS 格口，逗号分隔，如 '101,102'；空=无格口
  @p_send VARCHAR(4000) OUT
AS
  DECLARE @plc_no int, @qty int = 0, @chutes_hex varchar(2000) = '';
  DECLARE @rest varchar(500), @one varchar(64), @comma int, @digits varchar(64);
  DECLARE @i int, @ch char(1), @n int, @plc_int int;
BEGIN
  SET @plc_no = TRY_CAST(dbo.f_tools_mem('tts_plc_no') AS int);
  IF @plc_no IS NULL SET @plc_no = 1;

  -- 拆格口 → 转 PLC 地址 → 排序（用表变量排序实现由近到远）
  DECLARE @t TABLE (n int PRIMARY KEY);
  SET @rest = ISNULL(@chute_csv,'') + ',';
  WHILE CHARINDEX(',', @rest) > 0
  BEGIN
    SET @comma = CHARINDEX(',', @rest);
    SET @one = LTRIM(RTRIM(SUBSTRING(@rest, 1, @comma - 1)));
    SET @digits = '';
    SET @i = 1;
    WHILE @i <= LEN(@one)
    BEGIN
      SET @ch = SUBSTRING(@one, @i, 1);
      IF @ch BETWEEN '0' AND '9' SET @digits = @digits + @ch;
      SET @i = @i + 1;
    END
    IF @digits <> ''
    BEGIN
      SET @n = TRY_CAST(@digits AS int);
      IF @n IS NOT NULL AND NOT EXISTS (SELECT 1 FROM @t WHERE n = @plc_no*1000 + @n)
        INSERT INTO @t(n) VALUES (@plc_no*1000 + @n);
    END
    SET @rest = SUBSTRING(@rest, @comma + 1, LEN(@rest));
  END

  SELECT @qty = COUNT(*) FROM @t;
  SELECT @chutes_hex = STRING_AGG(RIGHT('0000' + dbo.f_tools_inttohex(n), 4), '')
         WITHIN GROUP (ORDER BY n) FROM @t;

  DECLARE @x int = LEN(@barcode_hex) / 2;  -- 条码字节数
  DECLARE @msg_len int = 32 + @x + @qty * 2;
  SET @p_send =
      'FCFC' + '08' + '00'
    + RIGHT('0000' + dbo.f_tools_inttohex(@msg_len), 4)
    + '00000000' + '0000'
    + @ParcelID_hex + '0000' + @BCR_hex + '0000'
    + RIGHT('0000' + dbo.f_tools_inttohex(@x), 4)
    + @barcode_hex
    + '0000' + '0000'                       -- Control_Status / LabelDevID（不贴标）
    + RIGHT('0000' + dbo.f_tools_inttohex(@qty), 4)
    + ISNULL(@chutes_hex,'')
    + 'FDFD';
END

GO

-- ----------------------------
-- Procedure structure for sp_tts_plc_make_0e
-- ----------------------------
DROP PROCEDURE [sp_tts_plc_make_0e]
GO

CREATE PROCEDURE [sp_tts_plc_make_0e]
  @block_code varchar(64),   -- TTS 格口编码，如 '101' / 'GK-0001'
  @lock bit,                 -- 1=封锁，0=解锁
  @p_send VARCHAR(4000) OUT
AS
  DECLARE @plc_no int, @digits varchar(64) = '', @i int, @ch char(1);
  DECLARE @n int, @plc_int int;
BEGIN
  SET @plc_no = TRY_CAST(dbo.f_tools_mem('tts_plc_no') AS int);
  IF @plc_no IS NULL SET @plc_no = 1;
  SET @i = 1;
  WHILE @i <= LEN(@block_code)
  BEGIN
    SET @ch = SUBSTRING(@block_code, @i, 1);
    IF @ch BETWEEN '0' AND '9' SET @digits = @digits + @ch;
    SET @i = @i + 1;
  END
  SET @n = TRY_CAST(@digits AS int);
  IF @n IS NULL SET @n = 0;
  SET @plc_int = @plc_no * 1000 + @n;
  SET @p_send =
      'FCFC' + '0E' + '00' + '001A' + '00000000' + '0000' + '0000'
    + RIGHT('0000' + dbo.f_tools_inttohex(@plc_int), 4)
    + '0015' + CASE WHEN @lock = 1 THEN '0001' ELSE '0000' END + '0000'
    + 'FDFD';
END

GO

-- ----------------------------
-- Procedure structure for sp_tts_plc_report_sort
-- ----------------------------
DROP PROCEDURE [sp_tts_plc_report_sort]
GO

CREATE PROCEDURE [sp_tts_plc_report_sort]
  @P_dvc_no VARCHAR(20),
  @p_Tel VARCHAR(4000),
  @P_CODE VARCHAR(100) OUT,
  @P_MSG VARCHAR(4000) OUT
AS
  DECLARE @barlen int, @barcode varchar(4000), @bc_tts varchar(4000);
  DECLARE @sortstate int, @alloc int, @exec int;
  DECLARE @grid3 varchar(8), @first3 varchar(8);
  DECLARE @st varchar(2), @reason varchar(32);
  DECLARE @ts varchar(20);
  DECLARE @v_DATE1 DATETIME = GETDATE(), @v_s INT = 0;
BEGIN
  BEGIN TRY
    SET @barlen  = dbo.f_tools_hextoint(SUBSTRING(@p_Tel, 45, 4));
    SET @barcode = dbo.f_tools_HEX_TO_CHAR(SUBSTRING(@p_Tel, 49, @barlen * 2));
    SET @sortstate = dbo.f_tools_hextoint(SUBSTRING(@p_Tel, 49 + @barlen*2, 4));
    SET @alloc   = dbo.f_tools_hextoint(SUBSTRING(@p_Tel, 53 + @barlen*2, 4));
    SET @exec    = dbo.f_tools_hextoint(SUBSTRING(@p_Tel, 57 + @barlen*2, 4));
    SET @P_CODE = '0';
  END TRY
  BEGIN CATCH
    SET @P_CODE = '-1'; SET @P_MSG = '[tts-plc-06]parse error:' + ERROR_MESSAGE();
    RETURN;
  END CATCH

  SET @bc_tts = REPLACE(@barcode, CHAR(5), ';');
  -- PLC 地址 → 3 位格口号（去 PLC 编号）
  SET @grid3  = RIGHT('00000' + CAST(@exec AS varchar(10)), 5);
  SET @grid3  = RIGHT(@grid3, 3);
  SET @first3 = RIGHT(RIGHT('00000' + CAST(@alloc AS varchar(10)), 5), 3);

  IF @sortstate = 0
  BEGIN
    SET @st = '1';
    -- 分到了非预期的格口 → expected
    SET @reason = CASE WHEN @exec <> @alloc THEN 'expected' ELSE '' END;
  END
  ELSE
  BEGIN
    SET @st = '2';
    SET @reason = CASE @sortstate
      WHEN 4 THEN 'reqerror'          -- 未反馈目的地
      WHEN 7 THEN 'reqerror'          -- 目的地地址无效
      WHEN 1 THEN 'reqerror'          -- 没读到条码
      WHEN 2 THEN 'reqerror'          -- 没读码器信息
      WHEN 9 THEN 'multicycle'       -- 超过最大循环圈数
      ELSE 'devicecheckerror' END;    -- 3/5/6/8/13/99 等设备侧异常
  END

  SET @ts = CAST(DATEDIFF_BIG(MILLISECOND,'1970-01-01',SYSUTCDATETIME()) AS varchar(20));
  DECLARE @body varchar(4000) =
    '{"name":"' + dbo.f_tools_mem('tts_deviceName')
    + '","barcode":"' + @bc_tts + '"'
    + ',"reqTime":' + @ts + ',"respTime":' + @ts
    + ',"status":' + @st + ',"errorReason":"' + @reason + '"'
    + ',"result":"' + @grid3 + '"'
    + ',"ext":"{\"errorCode\":\"\",\"layer\":\"\"}"}';
  INSERT INTO wcs_tools_feedback(type, flag, barcode, msg)
  VALUES ('tts_event', '0', @bc_tts, @body);

  UPDATE wcs_tools_parcel SET update_date=GETDATE()
  WHERE type='tts' AND barcode=@bc_tts;

  SET @P_MSG = '[tts-plc-06]barcode=' + @bc_tts + ',status=' + @st + ',chute=' + @grid3;
  SET @v_s = DATEDIFF(ms, @v_DATE1, GETDATE()) / 100;
  EXEC [dbo].[sp_create_wcs_log] 'tts_plc_06', @bc_tts, @first3, @grid3, NULL, @st,
    @P_CODE, @P_MSG, 'sp_tts_plc_report_sort', @v_s, @P_dvc_no, @p_Tel, NULL, NULL, NULL, NULL, NULL;
END

GO

-- ----------------------------
-- Procedure structure for sp_tts_plc_scan_report
-- ----------------------------
DROP PROCEDURE [sp_tts_plc_scan_report]
GO

CREATE PROCEDURE [sp_tts_plc_scan_report]
  @P_dvc_no VARCHAR(20),
  @p_Tel VARCHAR(4000),
  @P_CODE VARCHAR(100) OUT,
  @P_MSG VARCHAR(4000) OUT
AS
  DECLARE @ParcelID varchar(20), @BCR_NO varchar(20), @barlen int;
  DECLARE @barcode varchar(4000), @bc_tts varchar(4000);
  DECLARE @length int, @width int, @height int, @weight int;
  DECLARE @v_DATE1 DATETIME = GETDATE(), @v_s INT = 0;
BEGIN
  BEGIN TRY
    SET @ParcelID = CAST(dbo.f_tools_hextoint(SUBSTRING(@p_Tel, 25, 8)) AS varchar(20));
    SET @BCR_NO   = CAST(dbo.f_tools_hextoint(SUBSTRING(@p_Tel, 37, 4)) AS varchar(20));
    SET @barlen   = dbo.f_tools_hextoint(SUBSTRING(@p_Tel, 45, 4));
    SET @barcode  = dbo.f_tools_HEX_TO_CHAR(SUBSTRING(@p_Tel, 49, @barlen * 2));
    SET @length   = dbo.f_tools_hextoint(SUBSTRING(@p_Tel, 57 + @barlen*2, 4));
    SET @width    = dbo.f_tools_hextoint(SUBSTRING(@p_Tel, 61 + @barlen*2, 4));
    SET @height   = dbo.f_tools_hextoint(SUBSTRING(@p_Tel, 65 + @barlen*2, 4));
    SET @weight   = dbo.f_tools_hextoint(SUBSTRING(@p_Tel, 69 + @barlen*2, 8));  -- 克
    SET @P_CODE = '0';
  END TRY
  BEGIN CATCH
    SET @P_CODE = '-1'; SET @P_MSG = '[tts-plc-09]parse error:' + ERROR_MESSAGE();
    RETURN;
  END CATCH

  SET @bc_tts = REPLACE(@barcode, CHAR(5), ';');  -- 0x05 → ';'（TTS 侧）

  -- 登记包裹
  MERGE INTO wcs_tools_parcel AS t
  USING (SELECT @bc_tts AS bc) AS s ON t.type='tts' AND t.barcode=s.bc
  WHEN MATCHED THEN UPDATE SET length=CAST(@length AS varchar(20)),
      width=CAST(@width AS varchar(20)), height=CAST(@height AS varchar(20)),
      msg2=CAST(@weight*1000 AS varchar(20)),  -- 克 → 毫克（TTS 2.6 单位 mg）
      temp2=@BCR_NO, update_date=GETDATE()
  WHEN NOT MATCHED THEN INSERT (type, barcode, status, dvc_no, length, width, height, msg2, temp1, temp2)
      VALUES ('tts', @bc_tts, 'MEASURED', @P_dvc_no,
              CAST(@length AS varchar(20)), CAST(@width AS varchar(20)),
              CAST(@height AS varchar(20)), CAST(@weight*1000 AS varchar(20)), '0', @BCR_NO);

  -- 入队 TTS 2.6（去重）
  IF @bc_tts NOT IN ('', '??????????')
     AND NOT EXISTS (SELECT 1 FROM wcs_tools_feedback
                     WHERE type='tts_measure' AND barcode=@bc_tts AND flag IN ('0','1'))
  BEGIN
    -- TODO(UNIT): 长宽高单位待字节确认（文档 mm / 会上口头英尺·英寸），数值原样透传
    -- TODO(现场确认): deviceBlock 暂取 BCR_NO，字节侧若要求 GB-01-02-001 格式需映射表
    DECLARE @body varchar(4000) =
      '{"name":"' + dbo.f_tools_mem('tts_deviceName')
      + '","deviceBlock":"' + @BCR_NO + '"'
      + ',"barcode":"' + @bc_tts + '"'
      + ',"length":' + CAST(@length AS varchar(20))
      + ',"width":' + CAST(@width AS varchar(20))
      + ',"height":' + CAST(@height AS varchar(20))
      + ',"weight":' + CAST(@weight*1000 AS varchar(20))
      + ',"timestamp":' + CAST(DATEDIFF_BIG(MILLISECOND,'1970-01-01',SYSUTCDATETIME()) AS varchar(20)) + '}';
    INSERT INTO wcs_tools_feedback(type, flag, barcode, msg)
    VALUES ('tts_measure', '0', @bc_tts, @body);
  END

  SET @P_MSG = '[tts-plc-09]barcode=' + @bc_tts;
  SET @v_s = DATEDIFF(ms, @v_DATE1, GETDATE()) / 100;
  EXEC [dbo].[sp_create_wcs_log] 'tts_plc_09', @bc_tts, NULL, NULL, @BCR_NO, NULL,
    @P_CODE, @P_MSG, 'sp_tts_plc_scan_report', @v_s, @P_dvc_no, @p_Tel, NULL, NULL, NULL, NULL, NULL;
END

GO

-- ----------------------------
-- Procedure structure for sp_tts1_getsort_rev
-- ----------------------------
DROP PROCEDURE [sp_tts1_getsort_rev]
GO
CREATE PROCEDURE [sp_tts1_getsort_rev]
  @p_uuid varchar(100),
  @p_Send VARCHAR(4000),
  @p_Rev VARCHAR(4000),
  @P_CODE VARCHAR(4000) OUT,
  @P_MSG VARCHAR(4000) OUT
AS
  DECLARE @LOG varchar(1000)
    ,@BCR_NO VARCHAR(50) = '',@dvc_no VARCHAR(50) = '';
  DECLARE @v_DATE1 DATETIME = GETDATE(),@v_s INT = 0;
  DECLARE @id bigint,@barcode varchar(200),@ParcelID int,@TrackID int,@Induction int
    ,@msg2 varchar(500),@sCode varchar(50),@to_pos varchar(50)
    ,@tel_sn varchar(20),@url varchar(1000)
  DECLARE @code varchar(20),@msg varchar(200),@grids varchar(2000)
    ,@status varchar(20),@send varchar(8000),@cnt int,@maxc int
  BEGIN
    set @P_MSG = ''
    set @P_CODE = ''
    /* GET 类回包带 httpCode=200;httpMsg=OK##### 前缀，先截掉再解析 */
    IF CHARINDEX('#####',@p_Rev) > 0
      SET @p_Rev = SUBSTRING(@p_Rev, CHARINDEX('#####',@p_Rev) + 5, LEN(@p_Rev));
    BEGIN TRY
      /* 取 getsort 的 parcel 上下文（登记时以组装好的打包串原文关联） */
      SELECT @id=id,@barcode=barcode,@ParcelID=ParcelID,@TrackID=TrackID,@Induction=Induction,
             @dvc_no=dvc_no,@tel_sn=tel_sn,@url=url,
             @BCR_NO=ISNULL(NULLIF(temp2,''),bcr),@cnt=ISNULL(TRY_CAST(temp1 AS int),0)
      FROM wcs_tools_parcel WHERE msg=@p_Send AND type='tts1';

      /* 解析 TTS 应答信封 {code, msg, data[格口...]} */
      BEGIN TRY
        SET @code = json_value(@p_Rev, '$.code');
        SET @msg  = json_value(@p_Rev, '$.msg');
        SELECT @grids = STRING_AGG(value, ',') FROM OPENJSON(@p_Rev, '$.data');
      END TRY
      BEGIN CATCH
        set @msg2='json异常';
        set @status='103';
      END CATCH

      IF @status='103'
      BEGIN
        /* 回包解析失败：回异常口留痕 */
        set @to_pos = dbo.f_tools_mem('tts_exception_chute');
        INSERT INTO wcs_task(barcode,to_pos,task_type,receiver_name,shipment_id,url,status,plc_to_pos,sort_code)
          VALUES(@barcode,@to_pos,'tts1','', '',@url,@status,dbo.f_tools_WmsToPlc(@to_pos),'');
        exec sp_sd_make_msg '08',@dvc_no,@barcode,@to_pos,'0',@BCR_NO,@ParcelID,@TrackID,@Induction,@P_msg out;
        DELETE FROM wcs_tools_parcel WHERE id=@id;
      END
      ELSE IF ISNULL(@code,'') = '1003'
      BEGIN
        /* 未登录：不组 08、不删行；调用方重登后按 parcel.msg 重发 */
        set @status='1003';
        set @msg2=ISNULL(@msg2,'')+',relogin,';
        SET @P_CODE='1003';
      END
      ELSE IF ISNULL(@code,'') = '0' AND ISNULL(@grids,'') = '99999'
      BEGIN
        /* 云端还在等结果：入队 wcs_tools_feedback，轮询由队列链 getsort send/rev 处理 */
        INSERT INTO wcs_tools_feedback(type,flag,barcode,deviceName,deviceBlock,retry_count,create_date)
          VALUES('tts_getsort','0',@barcode,@dvc_no,@BCR_NO,0,GETDATE());

      END
      ELSE IF ISNULL(@code,'') = '0'
      BEGIN
        /* 拿到格口：写 task、组 08、删行收尾 */
        delete from wcs_task where barcode=@barcode and task_type='tts1';

        INSERT INTO wcs_task(barcode,to_pos,task_type,receiver_name,shipment_id,url,status,plc_to_pos,sort_code)
        SELECT @barcode, value, 'tts1', '', '', @url, '0', dbo.f_tools_WmsToPlc(value), ''
        FROM OPENJSON(@p_Rev, '$.data')
        WHERE ISNULL(value,'') <> '';

        SET @to_pos = @grids;
        IF ISNULL(@to_pos,'')=''
        BEGIN
          set @to_pos = dbo.f_tools_mem('tts_exception_chute');
          set @msg2=ISNULL(@msg2,'')+',no chute,';
        END
        IF @to_pos = '-1' set @msg2=ISNULL(@msg2,'')+',noread,hold,';
        set @status='0';

        exec sp_sd_make_msg '08',@dvc_no,@barcode,@to_pos,'0',@BCR_NO,@ParcelID,@TrackID,@Induction,@P_msg out;
        DELETE FROM wcs_tools_parcel WHERE id=@id;
      END
      ELSE
      BEGIN
        /* 其它失败 code：回约定异常口 */
        set @status=ISNULL(NULLIF(@code,''),'102');
        set @to_pos = dbo.f_tools_mem('tts_exception_chute');
        INSERT INTO wcs_task(barcode,to_pos,task_type,receiver_name,shipment_id,url,status,plc_to_pos,sort_code)
          VALUES(@barcode,@to_pos,'tts1','', '',@url,@status,dbo.f_tools_WmsToPlc(@to_pos),'');
        exec sp_sd_make_msg '08',@dvc_no,@barcode,@to_pos,'0',@BCR_NO,@ParcelID,@TrackID,@Induction,@P_msg out;
        DELETE FROM wcs_tools_parcel WHERE id=@id;
      END

      SET @LOG = '[tts1_getsort]'+isnull(@msg2,'')+ ISNULL(@barcode,'') +',msg='+isnull(@msg,'')
        +',code='+ isnull(@code,'') +',poll='+ CAST(@cnt AS varchar(10)) +',to_pos:' +isnull(@to_pos,'')
        +',Bcr' +isnull(@BCR_NO,'')+',id:'
        + isnull(CAST(@ParcelID AS VARCHAR),'')
    END TRY
    BEGIN CATCH
      SELECT @scode = ERROR_NUMBER(), @LOG = ERROR_MESSAGE()
    END CATCH

    set @p_code = CASE WHEN ISNULL(@P_CODE,'')='' THEN @LOG ELSE @P_CODE END
    SET @v_s = DATEDIFF(ms, @V_DATE1, GETDATE()) / 100
    set @p_msg = isnull(@p_msg,'')
    EXEC [dbo].[sp_create_wcs_log]
      'tts1_getsort',              /*1、作业名称 */
      @barcode,                    /*2、容器号 */
      @to_pos,                     /*3、应去口 */
      null,                        /*4、实际口 */
      @BCR_NO,                     /*5、读码器 */
      NULL,                        /*6、分拣状态 */
      @sCODE,                      /*7、执行代码 */
      @LOG,                        /*8、执行信息 */
      'sp_tts1_getsort_rev',       /*9、执行过程 */
      @v_s,                        /*10、执行时间 */
      'tts1_getsort',              /*11、dvc编号 */
      @p_send,                     /*12、备用1 */
      @p_Rev,                      /*13、备用2 */
      @P_msg,                      /*14、备用3 */
      NULL,                        /*15、任务状态 */
      NULL,                        /*16、上车状态 */
      null                         /*17、wcs任务号 */
  END
GO

-- ----------------------------
-- Procedure structure for sp_tts1_make_wms_msg
-- ----------------------------
DROP PROCEDURE [sp_tts1_make_wms_msg]
GO
/* ============================================================
   sp_tts1_make_wms_msg V5（2026-10-27）
   在现有 type='6'（实时调量方 2.6）基础上新增 type='7' 分支：组装 getsort（2.7 取格口）报文。
   type='7' 口径（照既有 getsort 实现与联调定版）：
   - GET 接口，无 body：@p_Send 尾段 '#####' 后为空（与 getsort_send 的 header+'#####' 一致）；
   - 参数串即签名串，顺序固定：name&deviceBlock&barcode&requestID&weight&length&width&height&timestamp&accessKey，
     requestID 每次新生成 GUID（去横线小写），timestamp 毫秒；
   - header 只挂 S-Auth（GET 无 Content-Type），占位格式与 type='6' 同款 #;# 分隔：
     {$TTS#;#<secretKey>#;#<参数串>$}，网关按参数串算 HMAC-SHA256；
   - url 段与 type='6' 不同：type='6' 只装 'accessKey=...'（POST 通道拼 ?accessKey），
     type='7' 装完整 'api/sorter/getSort?<参数串>'——消费方拼地址时 DVC_IP 后直拼本段，不要再补 '?'。
   type='6' 分支与原过程逐字未动。
   ============================================================ */
CREATE PROCEDURE [sp_tts1_make_wms_msg]
@type varchar(10),
@deviceName varchar(50),
@deviceBlock varchar(50),
@barcode VARCHAR(4000), @weight int, @length int, @width int, @height int,
@p_send VARCHAR(8000) OUT
AS
DECLARE @header VARCHAR(4000) = ''; /*设置的头*/
DECLARE @body VARCHAR(4000) = ''; /*发送的body*/
declare @url varchar(500)
declare @timestamp varchar(100)
declare @param varchar(4000)
BEGIN

/*查询扫码器配置表中该扫码器是否为实时请求扫码器,hc1四面扫 hc2换箱 hc3容器申请 hc4任务取消 hc5重量上报 hc6任务分流 0代表非实时请求*/
  if @type in ('6') /*任务分流：改拼调用量方的 JSON（同 sp_tts_measure_send） */
  begin
    SET @body = '{"name":"' + dbo.f_tools_mem('tts_deviceName_' + @deviceName)
              + '","deviceBlock":"' + ISNULL(@deviceBlock,'')
              + '","barcode":"' + ISNULL(@barcode,'')
              + '","length":' + CAST(ISNULL(@length,0) AS varchar(20))
              + ',"width":' + CAST(ISNULL(@width,0) AS varchar(20))
              + ',"height":' + CAST(ISNULL(@height,0) AS varchar(20))
              + ',"weight":' + CAST(ISNULL(@weight,0) AS varchar(20))
              + ',"timestamp":' + CAST(DATEDIFF_BIG(MILLISECOND,'1970-01-01',SYSUTCDATETIME()) AS varchar(20)) + '}';
    SET @header = 'Content-Type@@application/json;S-Auth@@{$TTS#;#'
                + dbo.f_tools_mem('tts_secretKey_' + @deviceName) + '#;#accessKey='
                + dbo.f_tools_mem('tts_accessKey_' + @deviceName) + '&paramBody=' + ISNULL(@body,'') + '$}';
    SET @url = 'accessKey=' + dbo.f_tools_mem('tts_accessKey_' + @deviceName);
    SET @p_Send = @url+'!!!!!'+ISNULL(@header,'') + '#####' + ISNULL(@body,'');
  end
  else if @type in ('7') /*取格口：组装 getsort（2.7）GET 报文 */
  begin
    SET @param = 'name=' + dbo.f_tools_mem('tts_deviceName_' + @deviceName)
              + '&deviceBlock=' + ISNULL(@deviceBlock,'')
              + '&barcode=' + ISNULL(@barcode,'')
              + '&requestID=' + LOWER(REPLACE(CAST(NEWID() AS VARCHAR(36)), '-', ''))
              + '&weight=' + CAST(ISNULL(@weight,0) AS varchar(20))
              + '&length=' + CAST(ISNULL(@length,0) AS varchar(20))
              + '&width=' + CAST(ISNULL(@width,0) AS varchar(20))
              + '&height=' + CAST(ISNULL(@height,0) AS varchar(20))
              + '&timestamp=' + CAST(DATEDIFF_BIG(MILLISECOND,'1970-01-01',SYSUTCDATETIME()) AS varchar(20))
              + '&accessKey=' + dbo.f_tools_mem('tts_accessKey_' + @deviceName);
    SET @header = 'S-Auth@@{$TTS#;#'
                + dbo.f_tools_mem('tts_secretKey_' + @deviceName) + '#;#'
                + ISNULL(@param,'') + '$}';
    SET @url = 'api/sorter/getSort?' + ISNULL(@param,'');
    SET @p_Send = @url+'!!!!!'+ISNULL(@header,'') + '#####';
  end
END
GO

-- ----------------------------
-- Procedure structure for sp_tts1_measure_rev
-- ----------------------------
DROP PROCEDURE [sp_tts1_measure_rev]
GO
CREATE PROCEDURE [sp_tts1_measure_rev]
  @p_uuid varchar(100),
  @p_Send VARCHAR(4000),
  @p_Rev VARCHAR(4000),
  @P_CODE VARCHAR(4000) OUT,
  @P_MSG VARCHAR(4000) OUT
AS
  DECLARE @LOG varchar(1000)
    ,@BCR_NO VARCHAR(50) = '',@dvc_no VARCHAR(50) = '';
  DECLARE @v_DATE1 DATETIME = GETDATE(),@v_s INT = 0;
  DECLARE  
     @barcode varchar(200),@ParcelID int,@TrackID int,@Induction int
    ,@msg2 varchar(500),@sCode varchar(50),@to_pos varchar(50)
    ,@tel_sn varchar(20),@url varchar(1000)
  DECLARE @code varchar(20),@msg varchar(200),@grids varchar(2000),@sf varchar(10),@eff varchar(4000)
    ,@status varchar(20),@use_barcode varchar(4000),@send varchar(2000)
  BEGIN
    set @P_MSG = ''
    set @P_CODE = ''
    BEGIN TRY
      /* 取实时请求的 parcel 上下文（入队时以组装好的 @p_Send 原文关联） */
      SELECT @barcode=barcode,@ParcelID=ParcelID,@TrackID=TrackID,@Induction=Induction,
             @dvc_no=dvc_no,@tel_sn=tel_sn,@url=url,@BCR_NO=temp2
      FROM wcs_tools_parcel WHERE msg=@p_Send AND type='tts1';

      /* 解析 TTS 应答信封 {code, msg, data{grids, sortFlag, barcode}} */
      BEGIN TRY
        SET @code = json_value(@p_Rev, '$.code');
        SET @msg  = json_value(@p_Rev, '$.msg');
        SELECT @grids = STRING_AGG(value, ',') FROM OPENJSON(@p_Rev, '$.data.grids');
        SET @sf  = json_value(@p_Rev, '$.data.sortFlag');   /* 'true' / 'false' */
        SET @eff = json_value(@p_Rev, '$.data.barcode');    /* 有效条码，后续交互以它为准 */
      END TRY
      BEGIN CATCH
        set @msg2='json异常';
        set @status='103';
      END CATCH

      SET @use_barcode = ISNULL(NULLIF(@eff,''), @barcode);

      IF @status='103'
      BEGIN
        /* 回包解析失败：回异常口留痕 */
        set @to_pos = dbo.f_tools_mem('tts_exception_chute');
        INSERT INTO wcs_task(barcode,to_pos,task_type,receiver_name,shipment_id,url,status,plc_to_pos,sort_code)
          VALUES(@barcode,@to_pos,'tts1','', '',@url,@status,dbo.f_tools_WmsToPlc(@to_pos),'');
        exec sp_sd_make_msg '08',@dvc_no,@barcode,@to_pos,'0',@BCR_NO,@ParcelID,@TrackID,@Induction,@P_msg out;
      END
      ELSE IF ISNULL(@code,'') = '1003'
      BEGIN
        /* 未登录：不组 08、不写 task；行保留，调用方重登后重发 measure */
        set @status='1003';
        set @msg2=ISNULL(@msg2,'')+',relogin,';
        SET @P_CODE='1003';
      END
      ELSE IF ISNULL(@code,'') = '0' AND ISNULL(@sf,'') = 'false'
      BEGIN
        SET @p_msg = isnull(@use_barcode,'') + ',post getsort'
        exec sp_tts1_make_wms_msg '7',@dvc_no,@dvc_no,@BCR_NO,@use_barcode,null,null,null,null,@send out
        set @P_MSG = '~~tts-getsort&' + isnull(@send,'')
        
        DELETE FROM wcs_tools_parcel WHERE ParcelID=@ParcelID AND type='tts1'
        INSERT INTO wcs_tools_parcel(barcode,type,status,ParcelID,TrackID,Induction,msg,bcr,dvc_no,tel_sn,url)
          VALUES (@barcode,'tts1','0',@ParcelID,@TrackID,@Induction,isnull(@send,''),@BCR_NO,@dvc_no,@tel_sn,@url)
      END
      ELSE IF ISNULL(@code,'') = '0'
      BEGIN
        /* sortFlag=true（或无 sortFlag）：格口已带回 */
        delete from wcs_task where barcode=@barcode and task_type='tts1';

        INSERT INTO wcs_task(barcode,to_pos,task_type,receiver_name,shipment_id,url,status,plc_to_pos,sort_code)
        SELECT @barcode, value, 'tts1', '', '', @url, '0', dbo.f_tools_WmsToPlc(value), ''
        FROM OPENJSON(@p_Rev, '$.data.grids')
        WHERE ISNULL(value,'') <> '';

        SET @to_pos = @grids;
        IF ISNULL(@to_pos,'')=''
        BEGIN
          set @to_pos = dbo.f_tools_mem('tts_exception_chute');
          set @msg2=ISNULL(@msg2,'')+',no chute,';
        END
        IF @to_pos = '-1' set @msg2=ISNULL(@msg2,'')+',noread,hold,';
        set @status='0';

        exec sp_sd_make_msg '08',@dvc_no,@barcode,@to_pos,'0',@BCR_NO,@ParcelID,@TrackID,@Induction,@P_msg out;
      END
      ELSE
      BEGIN
        /* 其它失败 code：回约定异常口 */
        set @status=ISNULL(NULLIF(@code,''),'102');
        set @to_pos = dbo.f_tools_mem('tts_exception_chute');
        INSERT INTO wcs_task(barcode,to_pos,task_type,receiver_name,shipment_id,url,status,plc_to_pos,sort_code)
          VALUES(@barcode,@to_pos,'tts1','', '',@url,@status,dbo.f_tools_WmsToPlc(@to_pos),'');
        exec sp_sd_make_msg '08',@dvc_no,@barcode,@to_pos,'0',@BCR_NO,@ParcelID,@TrackID,@Induction,@P_msg out;
      END

      SET @LOG = '[tts1_measure]'+isnull(@msg2,'')+ ISNULL(@barcode,'') +',msg='+isnull(@msg,'')
        +',code='+ isnull(@code,'') +',sortFlag='+isnull(@sf,'?')+',to_pos:' +isnull(@to_pos,'')
        +',Bcr' +isnull(@BCR_NO,'')+',id:'
        + isnull(CAST(@ParcelID AS VARCHAR),'')
    END TRY
    BEGIN CATCH
      SELECT @scode = ERROR_NUMBER(), @LOG = ERROR_MESSAGE()
    END CATCH

    set @p_code = CASE WHEN ISNULL(@P_CODE,'')='' THEN @LOG ELSE @P_CODE END
    SET @v_s = DATEDIFF(ms, @V_DATE1, GETDATE()) / 100
    set @p_msg = isnull(@p_msg,'')
    EXEC [dbo].[sp_create_wcs_log]
      'tts1_measure',              /*1、作业名称 */
      @barcode,                    /*2、容器号 */
      @to_pos,                     /*3、应去口 */
      null,                        /*4、实际口 */
      @BCR_NO,                     /*5、读码器 */
      NULL,                        /*6、分拣状态 */
      @sCODE,                      /*7、执行代码 */
      @LOG,                        /*8、执行信息 */
      'sp_tts1_measure_rev',       /*9、执行过程 */
      @v_s,                        /*10、执行时间 */
      'tts1_measure',              /*11、dvc编号 */
      @p_send,                     /*12、备用1 */
      @p_Rev,                      /*13、备用2 */
      @P_msg,                      /*14、备用3 */
      NULL,                        /*15、任务状态 */
      NULL,                        /*16、上车状态 */
      null                         /*17、wcs任务号 */
  END
GO

-- ----------------------------
-- Procedure structure for sp_tts1_sd_request
-- ----------------------------
DROP PROCEDURE [sp_tts1_sd_request]
GO
CREATE PROCEDURE [sp_tts1_sd_request]
 @P_dvc_no VARCHAR(20), @P_REV VARCHAR(4000), @P_SEND VARCHAR(4000) OUT, @P_CODE VARCHAR(10) OUT, @P_MSG VARCHAR(4000) OUT
AS
DECLARE @Tel_Head VARCHAR(10) = 'FCFC',/*小包起始符（FCFC）*/@Tel_End VARCHAR(10) = 'FDFD'  /*小包结束符（FDFD）*/
DECLARE @Barcode VARCHAR(500),@Destination01 VARCHAR(50),@BCR_NO VARCHAR(10)
DECLARE @TO_POS VARCHAR(50),@NO_EXCEPTION_NO VARCHAR(20),@ERR_EXCEPTION_NO VARCHAR(20)
DECLARE @v_s INT = 0,@v_DATE1 DATETIME = GETDATE()
DECLARE @barcode_len int,@v_msg varchar(4000)/*hc的报文 */
DECLARE @ParcelID int, @TrackID int,@Induction int

declare @weight int,@width int,@length int,@height int,@volume int,
  @send varchar(4000),@send2 varchar(4000),@url varchar(1000),
  @tel_sn varchar(20),@DestAmount int,@DestArr varchar(200), @tel_length int  
declare @id1 varchar(200),@pos2 varchar(50),@url_len int
BEGIN
  SET @P_SEND = ''
  SET @P_CODE = '0'
  SET @P_MSG  = ''

  BEGIN TRY
/* 1. 小报文长度 (2 Bytes: Byte 4) */
    SET @tel_sn = SUBSTRING(@p_REV, 9, 4)   
/* 2. 包裹号 (4 Bytes: Byte 12)  <- 修正: 原为 17,4，应为 25,8 */
    SET @ParcelID = dbo.f_tools_hextoint(SUBSTRING(@p_REV, 25, 8))
/* 3. 读码器 (2 Bytes: Byte 18)  <- 修正: 原为 21,4，应为 37,4 */
    SET @BCR_NO = CAST(dbo.f_tools_hextoint(SUBSTRING(@p_REV, 37, 4)) AS VARCHAR)
/* 4. 条码长度 (2 Bytes: Byte 22) <- 修正: 原为 25,4，应为 45,4 */
    SET @barcode_len = dbo.f_tools_hextoint(SUBSTRING(@p_REV, 45, 4))
/* 5. 条码内容 (x Bytes: Byte 24) <- 修正: 起始索引应为 49 */
    SET @Barcode = dbo.f_tools_HEX_TO_CHAR(SUBSTRING(@p_REV, 49, @barcode_len * 2))
/* 6. 货物长度 (2 Bytes: Byte 28+x) <- 修正: 起始索引应为 57 + len*2 */
    SET @length = dbo.f_tools_hextoint(SUBSTRING(@p_REV, 57 + @barcode_len * 2, 4)) 
/* 7. 货物宽度 (2 Bytes: Byte 30+x) <- 修正: 起始索引应为 61 + len*2 */
    SET @width = dbo.f_tools_hextoint(SUBSTRING(@p_REV, 61 + @barcode_len * 2, 4)) 
/* 8. 货物高度 (2 Bytes: Byte 32+x) <- 修正: 起始索引应为 65 + len*2 */
    SET @height = dbo.f_tools_hextoint(SUBSTRING(@p_REV, 65 + @barcode_len * 2, 4))
/* 9. 货物重量 (2 Bytes) <- 改为截取 4 个十六进制字符 */
    SET @weight = dbo.f_tools_hextoint(SUBSTRING(@p_REV, 69 + @barcode_len * 2, 4))
/* 10. 存图地址长度值 (2 Bytes) <- 紧跟重量之后，截取 4 个十六进制字符 */
    SET @url_len = dbo.f_tools_hextoint(SUBSTRING(@p_REV, 73 + @barcode_len * 2, 4))
/* 11. 存图地址字符 (N Bytes) <- 根据上一步算出的长度动态截取并转换为ASCII字符串 */    
    SET @url = dbo.f_tools_HEX_TO_CHAR(SUBSTRING(@p_REV, 77 + @barcode_len * 2, @url_len * 2)) 
	 /*12 track_id */
		SET @TrackID = dbo.f_tools_hextoint(SUBSTRING(@p_REV, 21, 4))      
	 /*13 Induction */
		SET @Induction = dbo.f_tools_hextoint(SUBSTRING(@p_REV, 33, 4)) 							 	 																				

		/*查询扫码器配置表中该扫码器是否为实时请求扫码器,hc1四面扫 hc2换箱  hc3容器申请   hc4任务取消  hc5重量上报  hc6任务分流  0代表非实时请求  7接力拣选*/
		IF isnull(dbo.f_tools_mem('bcr_type_'+@BCR_NO),'') in ('6') 
		  AND  @Barcode NOT IN ('','??????????', 'NoRead','NG','!!!!!','??????') 
			and isnull(dbo.f_tools_mem('sort_mode'),'') in ('1')
		BEGIN	
		  /*调用量方																		 								   */
			SET @p_msg = isnull(@Barcode ,'') + ',post measure'																				 								 																		 																																																															 		 					 
			exec sp_plc_make_wms_msg '6',@P_dvc_no,@P_dvc_no,@Barcode,@weight,@length,@width,@height,@send out
			set @p_send= '~~tts-measure&='+@send 																																																																																														 								 																		 																																																															 		 					 
																																																																																																																																																																																																	 																																																																																																 								 																		 																																																															 		 					 
    	DELETE FROM wcs_tools_parcel	WHERE ParcelID=@ParcelID	AND	type='cv'											 																										          
			INSERT INTO wcs_tools_parcel(barcode,type,status,ParcelID,TrackID,Induction,msg,bcr,dvc_no,tel_sn,url) 
			  VALUES (@Barcode,'cv','0',@ParcelID,@TrackID,@Induction,isnull(@send,''),@BCR_NO,@P_dvc_no,@tel_sn,@url)	
		END
		else
		begin		
			/*非实时请求 */
		  set @NO_EXCEPTION_NO=	dbo.f_tools_mem('bcr_no_'+@BCR_NO)
			set @ERR_EXCEPTION_NO= dbo.f_tools_mem('bcr_err_'+@BCR_NO)				    	

	  	IF @Barcode IN ('','??????????', 'NoRead','NG','!!!!!') 
	    BEGIN
		    SET @TO_POS = @ERR_EXCEPTION_NO
				set @barcode = 'NoRead'
		    SET @p_msg    = isnull(@barcode,'')+',ToPos:'
				
				INSERT INTO wcs_task( barcode,to_pos,task_type,shipment_id,url,status) 
				  values(@barcode,@to_pos,'cv','',@url,'') 	
  	  END
	    ELSE
	    BEGIN
			  update wcs_task set ParcelID= @ParcelID where barcode=@Barcode and task_type='offline'
							 					  
			  SELECT top 1 @TO_POS = TO_POS
			  FROM wcs_task WHERE barcode=@Barcode and task_type='offline'

	  	 	IF @@rowcount = 1
	    	BEGIN 				  																			 		 							 											 			 																																																																																																																																																																																																																																																																																																																																																			 			      
			    SET @p_Msg = isnull(@Barcode,'')+',ToPos:'
		    END
	    	ELSE
	  	 	BEGIN
			 	  SET @p_msg    = isnull(@Barcode,'')+',NoTask,ToPos:'
			 	  SET @TO_POS = @NO_EXCEPTION_NO
	    	END
	    end      										 																																								 																																			
	    		 		 					    
			exec sp_sd_make_msg	'08',@P_dvc_no ,@barcode,@to_pos,'0',@BCR_NO,@ParcelID,@trackId,@Induction,@P_SEND out  				 														       	
		END	
		
		SET @p_msg ='[sd_request]' + isnull(@p_msg,'') + ISNULL(@to_pos,'') +'('+ isnull(dbo.f_tools_WcsToPlc(@to_pos),'') +')'
						+ ',Bcr' + @BCR_NO + ',length-width-height='+cast(@length as varchar)+'-'+cast(@width as varchar)+'-'+cast(@height as varchar)
						+ ',weight='++cast(@weight as varchar)+',url='+isnull(@url,'')
						+',ParcelID:' + cast(@ParcelID as varchar)		  	
		
  END TRY
  BEGIN CATCH
    SELECT @p_code = ERROR_NUMBER(), @p_msg  = '目的地请求错误：' + ERROR_MESSAGE()
  END CATCH

  SET @v_s    = DATEDIFF(ms, @V_DATE1, GETDATE()) / 100
  set @p_msg = isnull(@p_msg,'')+',work_sec:'+cast(@v_s as varchar(10))
  EXEC [dbo].[sp_create_wcs_log]
	  	'sd_request',              /*1、作业名称 */
	  	@Barcode,                     /*2、容器号 */
	  	null,                           /*3、应去口 */
	  	NULL,                           /*4、实际口 */
		  @BCR_NO,                      /*5、读码器 */
		  NULL,                           /*6、分拣状态 */
		  @P_CODE,                        /*7、执行代码 */
	  	@p_msg,                         /*8、执行信息 */
		  'sp_tts_plc_request_dest',          /*9、执行过程 */
		  @v_s,                           /*10、执行时间 */
	  	@P_dvc_no,                      /*11、dvc编号 */  
	  	@p_REV,                         /*12、备用1 */
	  	@P_SEND,                         /*13、备用2 */
	  	null,                           /*14、备用3 */
		  NULL,                           /*15、任务状态 */  
		  null,	                        /*16、上车状态 */
			null                           /*16、wcs任务号 */
END
GO

-- ----------------------------
-- Procedure structure for sp_tts1_sd_rev
-- ----------------------------
DROP PROCEDURE [sp_tts1_sd_rev]
GO
CREATE PROCEDURE [sp_tts1_sd_rev]
  @P_dvc_no VARCHAR(20),
  @p_REV VARCHAR(4000),
  @P_SEND VARCHAR(2000) OUT,
  @p_Pack_Nr INT OUT,
  @P_CODE VARCHAR(20) OUT,
  @P_MSG VARCHAR(400) OUT
AS
  DECLARE @v_Pack_Head VARCHAR(10) = 'FEFEFEFE';
  DECLARE @v_Pack_End VARCHAR(10) = 'FFFFFFFF';
  DECLARE @v_Temp_Pack VARCHAR(4000) = '';
  DECLARE @v_Temp_Pack_Msg VARCHAR(4000) = '';
  DECLARE @v_Tel_Head VARCHAR(10) = 'FCFC';
  DECLARE @v_Tel_End VARCHAR(10) = 'FDFD';
  DECLARE @v_Temp_Tel VARCHAR(4000) = '';
  DECLARE @v_Temp_Tel_Msg VARCHAR(4000) = '';
  DECLARE @v_Send VARCHAR(4000) = '';
  DECLARE @v_log VARCHAR(4000) = '';
  DECLARE @V_CMD_CODE VARCHAR(10) = '';
BEGIN
  /* register_online：PLC 上线 → 登入系统 */
  IF @p_REV = 'register_online'
  BEGIN
    INSERT INTO wcs_tools_feedback(type, flag,deviceName) VALUES ('tts_login','0',dbo.f_tools_mem('tts_deviceName_'+@P_dvc_no)); 
    SET @P_SEND=''; SET @P_MSG='[tts-plc]register_online'; SET @p_Pack_Nr=0;
    RETURN;
  END
  /* register_offline：PLC 下线 → 登出系统、立即关闭心跳 */
  IF @p_REV = 'register_offline'
  BEGIN
    INSERT INTO wcs_tools_feedback(type, flag,deviceName) VALUES ('tts_logout','0',dbo.f_tools_mem('tts_deviceName_'+@P_dvc_no)); 
		UPDATE wcs_mem_config SET mem_item_value='0', update_date=GETDATE()
      WHERE mem_item_no='tts_session_online'; 
    SET @P_SEND=''; SET @P_MSG='[tts-plc]register_offline'; SET @p_Pack_Nr=0;
    RETURN;
  END

  SET @P_CODE      = '0'
  SET @P_SEND      = ''
  SET @P_MSG       = ''

  SET @v_Temp_Pack = @p_REV;

  WHILE @v_Temp_Pack <> ''
  BEGIN
    IF CHARINDEX(@v_Pack_End, @v_Temp_Pack, 5) > 53
      SET @v_Temp_Pack_Msg = SUBSTRING(@v_Temp_Pack, 53, CHARINDEX(@v_Pack_End, @v_Temp_Pack, 5) - 53)
    ELSE
      SET @v_Temp_Pack_Msg = ''
    
    /*小包处理*/
    SET @v_Temp_Tel   = @v_Temp_Pack_Msg;

    WHILE @v_Temp_Tel <> ''
    BEGIN
      set @v_send=''
      set @v_log=''
      
      SET @v_Temp_Tel_Msg = SUBSTRING(@v_Temp_Tel, 1, CHARINDEX(@v_Tel_End, @v_Temp_Tel, 3) + 3);
      
			if CHARINDEX(@v_Tel_End, @v_Temp_Tel_Msg , 1) =0 break; /*如果后面没有匹配的小报文就跳出循环 */
      
      SET @V_CMD_CODE     = SUBSTRING(@v_Temp_Tel_Msg, 5, 2);

      /* 目的地请求 */
      IF @V_CMD_CODE = '07'
        EXEC sp_sd_request_dest @P_dvc_no,@v_Temp_Tel_Msg, @v_send OUTPUT, @p_code OUTPUT, @v_log OUTPUT

      /* 分拣报告 */
      IF @V_CMD_CODE = '06'
        EXEC sp_sd_report_sort @P_dvc_no, @v_Temp_Tel_Msg, @p_code OUTPUT, @v_log OUTPUT
      
      /* 上车报告 */
      IF @V_CMD_CODE = '0A'
        EXEC sp_sd_report_induction @P_dvc_no, @v_Temp_Tel_Msg, @p_code OUTPUT, @v_log OUTPUT
       
			      /* 分拣确认 */
      IF @V_CMD_CODE = '0B'
        EXEC sp_sd_report_sort_confirm @P_dvc_no, @v_Temp_Tel_Msg, @p_code OUTPUT, @v_log OUTPUT 

      IF isnull(@v_log,'') <> ''
        SET @p_msg = @p_msg + @v_log + '####'  
				 
			IF isnull(@v_send,'') <> ''	 					 	  
        SET @p_send     = @p_send  +  @v_send
      
      SET @v_Temp_Tel     = SUBSTRING(@v_Temp_Tel, LEN(@v_Temp_Tel_Msg) + 1, LEN(@v_Temp_Tel));
    END

    SET @v_Temp_Pack  = SUBSTRING(@v_Temp_Pack, LEN(@v_Temp_Pack_Msg) + 53 + 8, LEN(@v_Temp_Pack))
  END
END
GO

-- ----------------------------
-- Procedure structure for sp_tts1_sd_send
-- ----------------------------
DROP PROCEDURE [sp_tts1_sd_send]
GO
CREATE PROCEDURE [sp_tts1_sd_send]
  @P_dvc_no VARCHAR(20),
  @p_send VARCHAR(4000) OUT,
  @P_CODE VARCHAR(100) OUT,
  @p_CMD_NAME VARCHAR(2000) OUT
AS
  DECLARE @v_hand_cmd_id VARCHAR(100);
DECLARE @V_CMD_NAME VARCHAR(4000);
DECLARE @V_CMD VARCHAR(4000);
declare @V_LMSG_TIME VARCHAR(100);
DECLARE
  @V_heartbeat VARCHAR(4000),
  @v_DATE1     DATETIME = GETDATE(),
  @v_s         INT = 0,
  @NAME        VARCHAR(4000),
  @CMD_NAME        VARCHAR(4000) = '' ;

BEGIN
  SELECT   TOP 1
           @v_hand_cmd_id = a.id, @V_CMD_NAME    = A.CMD_NAME, @V_CMD         = A.CMD
  FROM     wcs_tools_hand_cmd A
  WHERE    A.DVC_NO = @P_dvc_no
  ORDER BY a.id

  IF @@ROWCOUNT = 1
    BEGIN
      SET @p_send     = @V_CMD
      SET @p_CMD_NAME = @V_CMD_NAME

      /*执行完了就删除*/
      DELETE FROM wcs_tools_hand_cmd
      WHERE       id = @V_HAND_CMD_ID

      /*SET @p_send=dbo.VarCharToHex(@p_send); */

